create function finance_pilot_dev.current_membership_id() returns uuid language sql stable security definer set search_path='' as $$
 select d.id from finance_pilot_dev.memberships d join finance_pilot_dev.positions dp on dp.id=d.position_id
 join finance_pilot_dev_private.participants a on a.user_id=d.user_id and a.position_key=dp.key
 join public.memberships live on live.user_id=d.user_id and live.status='active'
 join public.positions lp on lp.id=live.position_id and lp.key=dp.key
 where d.user_id=auth.uid() and d.status='active' and exists(select 1 from finance_pilot_dev_private.settings where enabled) limit 1;
$$;
CREATE OR REPLACE FUNCTION finance_pilot_dev.current_user_has_permission(permission_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'finance_pilot_dev'
AS $function$
 select (
   exists(select 1 from finance_pilot_dev.memberships m join finance_pilot_dev.member_roles mr on mr.membership_id=m.id join finance_pilot_dev.role_permissions rp on rp.role_id=mr.role_id join finance_pilot_dev.permissions p on p.id=rp.permission_id where m.user_id=auth.uid() and m.status='active' and p.key=permission_key)
   or exists(select 1 from finance_pilot_dev.memberships m join finance_pilot_dev.position_permissions pp on pp.position_id=m.position_id join finance_pilot_dev.permissions p on p.id=pp.permission_id where m.user_id=auth.uid() and m.status='active' and p.key=permission_key)
   or exists(select 1 from finance_pilot_dev.memberships m join finance_pilot_dev.member_permission_overrides mpo on mpo.membership_id=m.id join finance_pilot_dev.permissions p on p.id=mpo.permission_id where m.user_id=auth.uid() and m.status='active' and p.key=permission_key and mpo.effect='allow')
 ) and not exists(select 1 from finance_pilot_dev.memberships m join finance_pilot_dev.member_permission_overrides mpo on mpo.membership_id=m.id join finance_pilot_dev.permissions p on p.id=mpo.permission_id where m.user_id=auth.uid() and m.status='active' and p.key=permission_key and mpo.effect='deny');
$function$;
