  id uuid primary key default extensions.gen_random_uuid(),
  entry_date date not null,
  description text not null check(length(trim(description)) between 1 and 500),
  status text not null default 'posted' check(status in ('posted','reversed')),
  source_type text,
  source_id text,
  created_by_membership_id uuid not null references finance_pilot_dev.memberships(id),
  posted_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  unique(source_type,source_id)
);

create table if not exists finance_pilot_dev.finance_next_journal_lines(
  id uuid primary key default extensions.gen_random_uuid(),
  journal_entry_id uuid not null references finance_pilot_dev.finance_next_journal_entries(id),
  line_number integer not null check(line_number>0),
  coa_code text not null references finance_pilot_dev.finance_coa(code),
  description text not null default '',
  debit numeric(18,2) not null default 0 check(debit>=0),
  credit numeric(18,2) not null default 0 check(credit>=0),
