create or replace function finance_pilot_dev.finance_next_post_journal(
  p_entry_date date,p_description text,p_lines jsonb,p_source_type text default null,p_source_id text default null
) returns uuid language plpgsql security definer set search_path=finance_pilot_dev as $$
declare actor uuid:=finance_pilot_dev.current_membership_id(); entry_id uuid; line jsonb; line_no integer:=0; total_debit numeric(18,2):=0; total_credit numeric(18,2):=0; account_row finance_pilot_dev.finance_coa%rowtype; line_debit numeric(18,2); line_credit numeric(18,2); service_key text; project text; project_ref uuid; month_state text;
begin
  if not finance_pilot_dev.current_user_has_permission('finance_next.manage') then raise exception 'Izin kelola Finance Pilot diperlukan.' using errcode='42501'; end if;
  if actor is null or p_entry_date is null or trim(coalesce(p_description,''))='' then raise exception 'Tanggal dan keterangan jurnal wajib diisi.'; end if;
  if coalesce(jsonb_typeof(p_lines),'')<>'array' or jsonb_array_length(p_lines)<2 then raise exception 'Jurnal harus memiliki minimal dua baris.'; end if;
  select status into month_state from finance_pilot_dev.finance_next_periods where period_month=date_trunc('month',p_entry_date)::date;
  if month_state in ('closed','close_requested') then raise exception 'Periode sudah ditutup atau menunggu penutupan.' using errcode='55000'; end if;
  for line in select value from jsonb_array_elements(p_lines) loop
    line_no:=line_no+1;
    select * into account_row from finance_pilot_dev.finance_coa where code=trim(coalesce(line->>'coa_code','')) and is_active;
    if not found then raise exception 'Akun % tidak ditemukan atau tidak aktif.',line->>'coa_code'; end if;
    line_debit:=coalesce(nullif(line->>'debit','')::numeric,0); line_credit:=coalesce(nullif(line->>'credit','')::numeric,0);
    if line_debit<0 or line_credit<0 or ((case when line_debit>0 then 1 else 0 end)+(case when line_credit>0 then 1 else 0 end))<>1 then raise exception 'Setiap baris harus berisi debit atau kredit positif.'; end if;
    service_key:=nullif(trim(line->>'service_line_key'),''); project_ref:=nullif(trim(line->>'project_id'),'')::uuid; project:=nullif(trim(line->>'project_name'),'');
    if account_row.account_class in ('Pendapatan','Beban Langsung Proyek') and service_key is null then raise exception 'Service line wajib untuk baris pendapatan dan HPP langsung.'; end if;
    if project_ref is not null then select name into project from finance_pilot_dev.projects where id=project_ref and deleted_at is null; if project is null then raise exception 'Project ID tidak ditemukan atau sudah diarsipkan.'; end if; end if;
    if account_row.account_class='Beban Langsung Proyek' and project_ref is null then raise exception 'Project ID wajib untuk setiap biaya langsung.'; end if;
    if service_key is not null and not exists(select 1 from finance_pilot_dev.finance_next_service_lines where service_line_key=service_key and is_active) then raise exception 'Service line tidak valid.'; end if;
    total_debit:=total_debit+line_debit; total_credit:=total_credit+line_credit;
  end loop;
  if total_debit<=0 or total_debit<>total_credit then raise exception 'Jurnal tidak seimbang: debit % dan kredit %.',total_debit,total_credit; end if;
  insert into finance_pilot_dev.finance_next_journal_entries(entry_date,description,source_type,source_id,created_by_membership_id)
  values(p_entry_date,trim(p_description),nullif(trim(p_source_type),''),nullif(trim(p_source_id),''),actor) returning id into entry_id;
  line_no:=0;
  for line in select value from jsonb_array_elements(p_lines) loop
    line_no:=line_no+1;
    project_ref:=nullif(trim(line->>'project_id'),'')::uuid;
    select name into project from finance_pilot_dev.projects where id=project_ref;
    insert into finance_pilot_dev.finance_next_journal_lines(journal_entry_id,line_number,coa_code,description,debit,credit,project_id,project_name,client,service_line_key)
    values(entry_id,line_no,trim(line->>'coa_code'),coalesce(trim(line->>'description'),''),coalesce(nullif(line->>'debit','')::numeric,0),coalesce(nullif(line->>'credit','')::numeric,0),project_ref,project,nullif(trim(line->>'client'),''),nullif(trim(line->>'service_line_key'),''));
  end loop;
  insert into finance_pilot_dev.finance_next_audit_logs(actor_user_id,actor_membership_id,action,entity_type,entity_id,after_data)
  values(auth.uid(),actor,'journal.post','finance_next_journal_entry',entry_id::text,jsonb_build_object('entry_date',p_entry_date,'description',trim(p_description),'line_count',line_no,'debit',total_debit,'credit',total_credit,'source_type',p_source_type,'source_id',p_source_id));
  return entry_id;
end $$;

create or replace function finance_pilot_dev.finance_next_request_period_change(p_period_month date,p_action text,p_reason text)
returns void language plpgsql security definer set search_path=finance_pilot_dev as $$
declare actor uuid:=finance_pilot_dev.current_membership_id(); current_status text;
begin
  if not finance_pilot_dev.current_user_has_permission('finance_next.manage') then raise exception 'Izin kelola Finance Pilot diperlukan.' using errcode='42501'; end if;
  if p_period_month is null or p_period_month<>date_trunc('month',p_period_month)::date or p_action not in ('close','reopen') or trim(coalesce(p_reason,''))='' then raise exception 'Periode, aksi, dan alasan yang valid wajib diisi.'; end if;
  select status into current_status from finance_pilot_dev.finance_next_periods where period_month=p_period_month for update;
  if current_status is null then current_status:='open'; end if;
  if (p_action='close' and current_status not in ('open','reopen_requested')) or (p_action='reopen' and current_status<>'closed') then raise exception 'Status periode tidak mengizinkan permintaan ini.'; end if;
  insert into finance_pilot_dev.finance_next_periods(period_month,status,requested_action,requested_by_membership_id,reviewed_by_membership_id,requested_at,reviewed_at,review_note)
  values(p_period_month,case p_action when 'close' then 'close_requested' else 'reopen_requested' end,p_action,actor,null,now(),null,trim(p_reason))
  on conflict(period_month) do update set status=excluded.status,requested_action=excluded.requested_action,requested_by_membership_id=excluded.requested_by_membership_id,reviewed_by_membership_id=null,requested_at=now(),reviewed_at=null,review_note=excluded.review_note,updated_at=now();
  insert into finance_pilot_dev.finance_next_audit_logs(actor_user_id,actor_membership_id,action,entity_type,entity_id,after_data,reason)
  values(auth.uid(),actor,'period.'||p_action||'.request','finance_next_period',p_period_month::text,jsonb_build_object('status',case p_action when 'close' then 'close_requested' else 'reopen_requested' end),trim(p_reason));
end $$;

create or replace function finance_pilot_dev.finance_next_review_period_change(p_period_month date,p_decision text,p_note text)
returns void language plpgsql security definer set search_path=finance_pilot_dev as $$
declare actor uuid:=finance_pilot_dev.current_membership_id(); period_row finance_pilot_dev.finance_next_periods%rowtype; next_status text;
begin
  if not finance_pilot_dev.current_user_has_permission('finance_next.approve') then raise exception 'Izin approver Finance Pilot diperlukan.' using errcode='42501'; end if;
  select * into period_row from finance_pilot_dev.finance_next_periods where period_month=p_period_month for update;
  if period_row.period_month is null or period_row.status not in ('close_requested','reopen_requested') then raise exception 'Tidak ada permintaan periode untuk ditinjau.'; end if;
  if period_row.requested_by_membership_id=actor then raise exception 'Pemohon tidak boleh menyetujui permintaannya sendiri.' using errcode='42501'; end if;
  if p_decision not in ('approve','reject') or (p_decision='reject' and trim(coalesce(p_note,''))='') then raise exception 'Keputusan tidak valid; alasan wajib saat menolak.'; end if;
  next_status:=case when p_decision='approve' and period_row.requested_action='close' then 'closed' when p_decision='approve' then 'open' when period_row.requested_action='close' then 'open' else 'closed' end;
  update finance_pilot_dev.finance_next_periods set status=next_status,reviewed_by_membership_id=actor,reviewed_at=now(),review_note=coalesce(nullif(trim(p_note),''),review_note),updated_at=now() where period_month=p_period_month;
  insert into finance_pilot_dev.finance_next_audit_logs(actor_user_id,actor_membership_id,action,entity_type,entity_id,before_data,after_data,reason)
  values(auth.uid(),actor,'period.'||period_row.requested_action||'.'||p_decision,'finance_next_period',p_period_month::text,jsonb_build_object('status',period_row.status),jsonb_build_object('status',next_status),coalesce(nullif(trim(p_note),''),period_row.review_note));
end $$;

revoke all on function finance_pilot_dev.finance_next_post_journal(date,text,jsonb,text,text) from public,anon;
revoke all on function finance_pilot_dev.finance_next_request_period_change(date,text,text) from public,anon;
revoke all on function finance_pilot_dev.finance_next_review_period_change(date,text,text) from public,anon;
grant execute on function finance_pilot_dev.finance_next_post_journal(date,text,jsonb,text,text) to authenticated;
grant execute on function finance_pilot_dev.finance_next_request_period_change(date,text,text) to authenticated;
grant execute on function finance_pilot_dev.finance_next_review_period_change(date,text,text) to authenticated;

-- REVIEW ONLY: additive Finance Pilot integration. Do not run on production before approval.
-- Reuses finance_coa, finance_documents, projects, pipeline_leads and finance_next ledger.
-- No legacy backfill, bank snapshot mutation, automatic cutover or production test data.
create schema if not exists finance_pilot_dev_private;
revoke all on schema finance_pilot_dev_private from public,anon,authenticated;

create or replace function finance_pilot_dev_private.actor(p_action text) returns uuid
language plpgsql stable security definer set search_path='' as $$
declare actor uuid; position_key text;
begin
 select m.id,p.key into actor,position_key from finance_pilot_dev.memberships m join finance_pilot_dev.positions p on p.id=m.position_id
 where m.user_id=auth.uid() and m.status='active' and m.id=finance_pilot_dev.current_membership_id();
 if actor is null then raise exception 'Keanggotaan aktif diperlukan.' using errcode='42501'; end if;
 if p_action='manage' and (position_key<>'coo' or not finance_pilot_dev.current_user_has_permission('finance_next.manage')) then
   raise exception 'Operasional finance hanya untuk COO.' using errcode='42501';
 elsif p_action='approve' and (position_key<>'ceo' or not finance_pilot_dev.current_user_has_permission('finance_next.approve')) then
   raise exception 'Approval finansial hanya untuk CEO.' using errcode='42501';
 elsif p_action='view' and (position_key not in ('coo','ceo') or not finance_pilot_dev.current_user_has_permission('finance_next.view')) then
   raise exception 'Laporan finansial hanya untuk COO dan CEO.' using errcode='42501';
 elsif p_action not in ('view','manage','approve') then raise exception 'Aksi tidak valid.'; end if;
 return actor;
end $$;

-- Position grants preserve existing membership/role/override infrastructure; admin role cannot bypass actor().
insert into finance_pilot_dev.position_permissions(position_id,permission_id)
select pos.id,p.id from finance_pilot_dev.positions pos cross join finance_pilot_dev.permissions p
where (pos.key='coo' and p.key in ('finance_next.view','finance_next.manage'))
 or (pos.key='ceo' and p.key in ('finance_next.view','finance_next.approve')) on conflict do nothing;

create table finance_pilot_dev.finance_next_requests(
 id uuid primary key default extensions.gen_random_uuid(),
 request_key uuid not null unique,
 kind text not null check(kind in ('journal','invoice','receipt','target','policy','funds','budget','reversal','project_closure','account')),
 state text not null default 'draft' check(state in ('draft','submitted','approved','rejected','posted')),
 payload jsonb not null check(jsonb_typeof(payload)='object'),
 prepared_by uuid not null references finance_pilot_dev.memberships(id),
 approved_by uuid references finance_pilot_dev.memberships(id),
 submitted_at timestamptz, reviewed_at timestamptz, review_note text,
 result_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table finance_pilot_dev.finance_next_project_controls(
 project_id uuid primary key references finance_pilot_dev.projects(id),
 service_line_key text not null references finance_pilot_dev.finance_next_service_lines(service_line_key),
 contract_value numeric(18,2) not null check(contract_value>=0),
 budgeted_hpp numeric(18,2) not null check(budgeted_hpp>=0),
 committed_cost numeric(18,2) not null default 0 check(committed_cost>=0),
 delivery_confirmed_by uuid references finance_pilot_dev.memberships(id), delivery_confirmed_at timestamptz,
 handover_evidence text, financially_closed_at timestamptz, financially_closed_by uuid references finance_pilot_dev.memberships(id),
 approved_request_id uuid not null references finance_pilot_dev.finance_next_requests(id)
);
create table finance_pilot_dev.finance_next_reconciliations(
 id uuid primary key default extensions.gen_random_uuid(), request_key uuid not null unique,
 bank_coa_code text not null references finance_pilot_dev.finance_coa(code), as_of_date date not null,
 statement_balance numeric(18,2) not null, book_balance numeric(18,2) not null,
 ledger_fingerprint text not null, evidence_path text not null,
 prepared_by uuid not null references finance_pilot_dev.memberships(id), created_at timestamptz not null default now(),
 check(statement_balance=book_balance)
);
-- Existing document identity is canonical; nullable additions do not reclassify old records.
alter table finance_pilot_dev.finance_documents add column if not exists finance_pilot boolean;
alter table finance_pilot_dev.finance_documents add column if not exists pilot_project_id uuid references finance_pilot_dev.projects(id);
alter table finance_pilot_dev.finance_documents add column if not exists pilot_service_line_key text references finance_pilot_dev.finance_next_service_lines(service_line_key);
alter table finance_pilot_dev.finance_documents add column if not exists pilot_journal_id uuid references finance_pilot_dev.finance_next_journal_entries(id);
alter table finance_pilot_dev.finance_documents add column if not exists pilot_deposit_coa_code text references finance_pilot_dev.finance_coa(code);
alter table finance_pilot_dev.finance_documents add column if not exists pilot_evidence_path text;
alter table finance_pilot_dev.finance_next_journal_entries add column if not exists reversal_of_id uuid references finance_pilot_dev.finance_next_journal_entries(id);
create unique index finance_next_one_reversal on finance_pilot_dev.finance_next_journal_entries(reversal_of_id) where reversal_of_id is not null;
create index finance_next_requests_state_idx on finance_pilot_dev.finance_next_requests(state,kind,created_at);
create index finance_next_documents_idx on finance_pilot_dev.finance_documents(document_date,document_type) where finance_pilot is true;

create or replace function finance_pilot_dev_private.can_view() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from finance_pilot_dev.memberships m join finance_pilot_dev.positions p on p.id=m.position_id
 where m.user_id=auth.uid() and m.status='active' and p.key in ('coo','ceo'))
 and finance_pilot_dev.current_user_has_permission('finance_next.view');
$$;
-- Private helper usable by RLS, not an exposed RPC.
grant usage on schema finance_pilot_dev_private to authenticated;
grant execute on function finance_pilot_dev_private.can_view() to authenticated;
alter table finance_pilot_dev.finance_next_requests enable row level security;
alter table finance_pilot_dev.finance_next_project_controls enable row level security;
alter table finance_pilot_dev.finance_next_reconciliations enable row level security;
create policy finance_next_requests_read on finance_pilot_dev.finance_next_requests for select to authenticated using(finance_pilot_dev_private.can_view());
create policy finance_next_controls_read on finance_pilot_dev.finance_next_project_controls for select to authenticated using(finance_pilot_dev_private.can_view());
create policy finance_next_reconciliations_read on finance_pilot_dev.finance_next_reconciliations for select to authenticated using(finance_pilot_dev_private.can_view());
grant select on finance_pilot_dev.finance_next_requests,finance_pilot_dev.finance_next_project_controls,finance_pilot_dev.finance_next_reconciliations to authenticated;
revoke insert,update,delete,truncate on finance_pilot_dev.finance_next_requests,finance_pilot_dev.finance_next_project_controls,finance_pilot_dev.finance_next_reconciliations from anon,authenticated;
-- Restrictive policies prevent old broad role grants exposing pilot records. Legacy access unchanged.
create policy finance_pilot_document_boundary on finance_pilot_dev.finance_documents as restrictive to authenticated
 using(finance_pilot is not true or finance_pilot_dev_private.can_view()) with check(finance_pilot is not true);
create policy finance_pilot_document_read on finance_pilot_dev.finance_documents for select to authenticated using(finance_pilot is true and finance_pilot_dev_private.can_view());

do $$ declare t text; begin
 foreach t in array array['finance_next_service_lines','finance_next_periods','finance_next_journal_entries','finance_next_journal_lines','finance_next_legacy_mappings','finance_next_audit_logs'] loop
 execute format('create policy finance_pilot_role_boundary on finance_pilot_dev.%I as restrictive for select to authenticated using(finance_pilot_dev_private.can_view())',t);
 end loop;
end $$;

create or replace function finance_pilot_dev_private.audit(p_action text,p_entity text,p_id text,p_before jsonb,p_after jsonb,p_reason text default null)
returns void language sql security definer set search_path='' as $$
 insert into finance_pilot_dev.finance_next_audit_logs(actor_user_id,actor_membership_id,action,entity_type,entity_id,before_data,after_data,reason)
 values(auth.uid(),finance_pilot_dev.current_membership_id(),p_action,p_entity,p_id,p_before,p_after,p_reason);
$$;
create or replace function finance_pilot_dev_private.policy() returns jsonb language sql stable security definer set search_path='' as $$
 select payload from finance_pilot_dev.finance_next_requests where kind='policy' and state='posted' order by reviewed_at desc,id limit 1;
$$;
create or replace function finance_pilot_dev_private.evidence(p_path text) returns void language plpgsql security definer set search_path='' as $$
begin
 if p_path is null or not exists(select 1 from storage.objects where bucket_id='finance-pilot-dev-evidence' and name=p_path) then
 raise exception 'Bukti privat wajib diunggah sebelum posting.'; end if;
end $$;
create or replace function finance_pilot_dev_private.lock_period(p_date date) returns void language plpgsql security definer set search_path='' as $$
declare s text;
begin
 if p_date is null then raise exception 'Tanggal wajib.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('finance-dev-period:'||date_trunc('month',p_date)::date::text,0));
 select status into s from finance_pilot_dev.finance_next_periods where period_month=date_trunc('month',p_date)::date for update;
 if s is not null and s<>'open' then raise exception 'Periode belum terbuka: %',s using errcode='55000'; end if;
end $$;

-- Internal ledger writer. Every source is unique; repeated executions return the existing entry.
create or replace function finance_pilot_dev_private.post(p_date date,p_description text,p_lines jsonb,p_source_type text,p_source_id text,p_reversal uuid default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare eid uuid; l jsonb; a finance_pilot_dev.finance_coa%rowtype; d numeric(18,2); c numeric(18,2); td numeric(18,2):=0; tc numeric(18,2):=0; n int:=0; pr uuid; sk text; ctl finance_pilot_dev.finance_next_project_controls%rowtype;
begin
 perform finance_pilot_dev_private.actor('manage');
 perform finance_pilot_dev_private.lock_period(p_date);
 perform pg_advisory_xact_lock(hashtextextended('finance-source:'||p_source_type||':'||p_source_id,0));
 select id into eid from finance_pilot_dev.finance_next_journal_entries where source_type=p_source_type and source_id=p_source_id;
 if eid is not null then return eid; end if;
 if nullif(trim(p_description),'') is null or length(p_description)>500 or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)<2 then raise exception 'Jurnal minimal dua baris dan keterangan wajib.'; end if;
 for l in select value from jsonb_array_elements(p_lines) loop
 select * into a from finance_pilot_dev.finance_coa where code=l->>'coa_code' and is_active;
 if a.code is null or a.account_class like 'Kontrol%' or a.account_class='Kontra Beban' then raise exception 'Akun ledger aktif diperlukan; akun kontrol tidak boleh diposting.'; end if;
 d:=coalesce(nullif(l->>'debit','')::numeric,0); c:=coalesce(nullif(l->>'credit','')::numeric,0);
 if d<0 or c<0 or ((d>0)::int+(c>0)::int)<>1 or d::text in ('NaN','Infinity','-Infinity') or c::text in ('NaN','Infinity','-Infinity') then raise exception 'Debit/kredit tidak valid.'; end if;
 pr:=nullif(l->>'project_id','')::uuid; sk:=nullif(l->>'service_line_key','');
 if pr is not null then
   select * into ctl from finance_pilot_dev.finance_next_project_controls where project_id=pr;
   if not exists(select 1 from finance_pilot_dev.projects where id=pr and deleted_at is null and status not in ('Cancelled','Archived')) then raise exception 'Project tidak aktif.'; end if;
   if ctl.financially_closed_at is not null and p_reversal is null then raise exception 'Project sudah ditutup finansial.'; end if;
   if ctl.service_line_key is not null and sk is distinct from ctl.service_line_key then raise exception 'Service line harus diwarisi dari project.'; end if;
 end if;
 if a.account_class in ('Pendapatan','Beban Langsung Proyek') and not exists(select 1 from finance_pilot_dev.finance_next_service_lines where service_line_key=sk and is_active) then raise exception 'Service line wajib.'; end if;
 if a.account_class='Beban Langsung Proyek' and (pr is null or ctl.project_id is null) then raise exception 'Biaya langsung membutuhkan project dan budget disetujui.'; end if;
 td:=td+d; tc:=tc+c;
 end loop;
 if td<=0 or td<>tc then raise exception 'Jurnal tidak seimbang.'; end if;
 insert into finance_pilot_dev.finance_next_journal_entries(entry_date,description,source_type,source_id,created_by_membership_id,reversal_of_id)
 values(p_date,trim(p_description),p_source_type,p_source_id,finance_pilot_dev.current_membership_id(),p_reversal) returning id into eid;
 for l in select value from jsonb_array_elements(p_lines) loop
 n:=n+1; pr:=nullif(l->>'project_id','')::uuid;
 insert into finance_pilot_dev.finance_next_journal_lines(journal_entry_id,line_number,coa_code,description,debit,credit,project_id,project_name,client,service_line_key)
 values(eid,n,l->>'coa_code',coalesce(l->>'description',''),coalesce(nullif(l->>'debit','')::numeric,0),coalesce(nullif(l->>'credit','')::numeric,0),pr,(select name from finance_pilot_dev.projects where id=pr),nullif(l->>'client',''),nullif(l->>'service_line_key',''));
 end loop;
 perform finance_pilot_dev_private.audit('journal.post','journal',eid::text,null,jsonb_build_object('source_type',p_source_type,'source_id',p_source_id,'debit',td,'credit',tc));
 return eid;
end $$;

-- The original RPC lacks evidence/idempotency/approval and must no longer bypass the workflow.
create or replace function finance_pilot_dev.finance_next_post_journal(p_entry_date date,p_description text,p_lines jsonb,p_source_type text default null,p_source_id text default null)
returns uuid language plpgsql security definer set search_path='' as $$
begin perform finance_pilot_dev_private.actor('manage'); raise exception 'Gunakan workflow draft Finance Pilot dengan bukti dan request key.'; end $$;

create or replace function finance_pilot_dev_private.immutable() returns trigger language plpgsql set search_path='' as $$
begin raise exception 'Record posted/audit tidak boleh diubah atau dihapus; gunakan reversal.' using errcode='55000'; end $$;
create trigger finance_pilot_entries_immutable before update or delete on finance_pilot_dev.finance_next_journal_entries for each row execute function finance_pilot_dev_private.immutable();
create trigger finance_pilot_lines_immutable before update or delete on finance_pilot_dev.finance_next_journal_lines for each row execute function finance_pilot_dev_private.immutable();
create trigger finance_pilot_audit_immutable before update or delete on finance_pilot_dev.finance_next_audit_logs for each row execute function finance_pilot_dev_private.immutable();

-- Protect pilot documents even when an older Finance RPC is invoked.
create or replace function finance_pilot_dev_private.document_guard() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if TG_OP='INSERT' then
   if new.finance_pilot is not true and exists(select 1 from finance_pilot_dev.finance_documents where id=new.linked_invoice_id and finance_pilot is true) then raise exception 'Invoice pilot wajib dibayar melalui workflow pilot.'; end if;
   return new;
 end if;
 if old.finance_pilot is true then
   if TG_OP='DELETE' or new.deleted_at is not null or new.finance_pilot is distinct from old.finance_pilot then raise exception 'Dokumen pilot tidak boleh dihapus.'; end if;
   if old.pilot_journal_id is not null then
     if (to_jsonb(new)-array['paid','balance','status','updated_at','updated_by_membership_id']) is distinct from (to_jsonb(old)-array['paid','balance','status','updated_at','updated_by_membership_id']) then raise exception 'Nilai dokumen posted immutable.'; end if;
     if new.status='Void' then
       if not exists(select 1 from finance_pilot_dev.finance_next_journal_entries where reversal_of_id=old.pilot_journal_id) or new.paid<>old.paid or new.balance<>old.balance then raise exception 'Void memerlukan reversal nyata dan tidak boleh mengubah nilai sumber.'; end if;
     elsif old.document_type='receipt' or new.paid<>(select coalesce(sum(d.total),0) from finance_pilot_dev.finance_documents d where d.finance_pilot is true and d.linked_invoice_id=old.id and d.document_type='receipt' and d.pilot_journal_id is not null and not exists(select 1 from finance_pilot_dev.finance_next_journal_entries e where e.reversal_of_id=d.pilot_journal_id)) or new.balance<>new.total-new.paid then raise exception 'Saldo invoice harus berasal dari receipt ledger.'; end if;
   end if;
 end if;
 if TG_OP='DELETE' then return old; end if;
 return new;
end $$;
create trigger finance_pilot_document_guard before insert or update or delete on finance_pilot_dev.finance_documents for each row execute function finance_pilot_dev_private.document_guard();

-- Evidence is immutable/private; no public URL, upsert or delete policy.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('finance-pilot-dev-evidence','finance-pilot-dev-evidence',false,10485760,array['application/pdf','image/png','image/jpeg']) on conflict(id) do nothing;
create policy finance_pilot_dev_evidence_upload on storage.objects for insert to authenticated with check(
 bucket_id='finance-pilot-dev-evidence' and (storage.foldername(name))[1]=auth.uid()::text
 and exists(select 1 from finance_pilot_dev.memberships m join finance_pilot_dev.positions p on p.id=m.position_id where m.user_id=auth.uid() and m.status='active' and p.key='coo')
 and finance_pilot_dev.current_user_has_permission('finance_next.manage'));
create policy finance_pilot_dev_evidence_read on storage.objects for select to authenticated using(bucket_id='finance-pilot-dev-evidence' and finance_pilot_dev_private.can_view());

create or replace function finance_pilot_dev.finance_pilot_access() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid; pk text;
begin
 actor:=finance_pilot_dev_private.actor('view');
 select p.key into pk from finance_pilot_dev.memberships m join finance_pilot_dev.positions p on p.id=m.position_id where m.id=actor;
 return jsonb_build_object('membership_id',actor,'position',pk,'manage',pk='coo' and finance_pilot_dev.current_user_has_permission('finance_next.manage'),'approve',pk='ceo' and finance_pilot_dev.current_user_has_permission('finance_next.approve'));
end $$;

create or replace function finance_pilot_dev.finance_pilot_save_request(p_key uuid,p_kind text,p_payload jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare actor uuid:=finance_pilot_dev_private.actor('manage'); r finance_pilot_dev.finance_next_requests%rowtype; rid uuid;
begin
 if p_key is null or p_kind not in ('journal','invoice','receipt','target','policy','funds','budget','reversal','project_closure','account') or coalesce(jsonb_typeof(p_payload),'')<>'object' then raise exception 'Draft tidak valid.'; end if;
 if p_kind='target' and (p_payload->>'fiscal_year' is null or p_payload->>'fiscal_year' !~ '^[0-9]{4}$') then raise exception 'Tahun fiscal draft wajib empat digit.'; end if;
 if length(p_payload::text)>100000 then raise exception 'Payload terlalu besar.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('finance-dev-request:'||p_key::text,0));
 select * into r from finance_pilot_dev.finance_next_requests where request_key=p_key for update;
 -- Replay must not recalculate a payment against its already-reduced liability.
 if r.id is not null and r.state<>'draft' and p_kind='journal' and p_payload->>'business_event' not in ('manual','opening_adjustment') then
  if r.prepared_by<>actor or r.kind<>p_kind then raise exception 'Request key milik operasi lain.' using errcode='42501'; end if;
  if r.payload-'lines'=p_payload-'lines' then return r.id; end if;
  raise exception 'Payload request yang sudah submit tidak boleh berubah.';
 end if;
 if p_kind='journal' then p_payload:=p_payload||jsonb_build_object('lines',finance_pilot_dev_private.template(p_payload)); end if;
 if r.id is not null then
   if r.prepared_by<>actor or r.kind<>p_kind then raise exception 'Request key milik operasi lain.' using errcode='42501'; end if;
   if r.state<>'draft' then
     if r.payload=p_payload then return r.id; end if;
     raise exception 'Payload request yang sudah submit tidak boleh berubah.';
   end if;
   update finance_pilot_dev.finance_next_requests set payload=p_payload,updated_at=now() where id=r.id; rid:=r.id;
 else
   insert into finance_pilot_dev.finance_next_requests(request_key,kind,payload,prepared_by) values(p_key,p_kind,p_payload,actor) returning id into rid;
 end if;
 perform finance_pilot_dev_private.audit('draft.save',p_kind,rid::text,to_jsonb(r),p_payload);
 return rid;
end $$;

create or replace function finance_pilot_dev_private.validate_policy(p jsonb) returns void language plpgsql security definer set search_path='' as $$
declare k text; ac text; mapped text[];
begin
 if (p->>'approval_threshold')::numeric<0 or (p->>'approval_threshold') is null or (p->>'fiscal_start')::int not between 1 and 12 or p->>'fiscal_start' is null then raise exception 'Threshold dan tahun fiskal harus diputuskan eksplisit.'; end if;
 if (p->>'approval_threshold')::numeric::text in ('NaN','Infinity','-Infinity') then raise exception 'Threshold tidak valid.'; end if;
 foreach k in array array['cash','receivable','payable','advance','tax_payable','retained_earnings','distribution_payable','fixed_asset','related_receivable'] loop
   select account_class into ac from finance_pilot_dev.finance_coa where code=p->'accounts'->>k and is_active;
   if ac is null or (k in ('cash','receivable','fixed_asset','related_receivable') and ac<>'Aset')
    or (k in ('payable','advance','tax_payable','distribution_payable') and ac<>'Kewajiban') or (k='retained_earnings' and ac<>'Ekuitas') then raise exception 'Mapping akun % belum sesuai.',k; end if;
 end loop;
 select array_agg(value) into mapped from jsonb_each_text(p->'accounts');
 if (select count(*) from unnest(mapped))<>(select count(distinct v) from unnest(mapped) v) then raise exception 'Akun kontrol berbeda tidak boleh memakai saldo yang sama.'; end if;
 if exists(select 1 from finance_pilot_dev.finance_next_journal_entries) and finance_pilot_dev_private.policy()->'accounts' is distinct from p->'accounts' then raise exception 'Mapping akun posted memerlukan rencana migrasi terpisah; perubahan diblokir.'; end if;
 if exists(select 1 from finance_pilot_dev.finance_next_requests where kind='target' and state='posted') and finance_pilot_dev_private.policy()->>'fiscal_start' is distinct from p->>'fiscal_start' then raise exception 'Kalender fiscal bertarget aktif tidak boleh diubah tanpa migrasi.'; end if;
 if nullif(trim(p->>'reason'),'') is null then raise exception 'Alasan perubahan kebijakan wajib.'; end if;
end $$;

create or replace function finance_pilot_dev_private.validate(p_kind text,p jsonb) returns numeric
language plpgsql security definer set search_path='' as $$
declare amount numeric(18,2); ac jsonb:=finance_pilot_dev_private.policy()->'accounts'; total numeric(18,2); l jsonb; pr uuid; required_field text; ctl finance_pilot_dev.finance_next_project_controls%rowtype;
begin
 if p_kind='journal' then
  foreach required_field in array array['date','description','business_event','reference','evidence_path'] loop if nullif(trim(p->>required_field),'') is null then raise exception 'Field wajib: %',required_field; end if; end loop;
 elsif p_kind='invoice' then
  foreach required_field in array array['date','due_date','client','item_description','quantity','unit_price','discount','tax','management_fee','other_fees','service_line_key','installment_scheme','evidence_path','milestone_evidence'] loop if nullif(trim(p->>required_field),'') is null then raise exception 'Field wajib: %',required_field; end if; end loop;
 elsif p_kind='receipt' then
  foreach required_field in array array['date','invoice_id','amount','deposit_coa_code','reference','evidence_path'] loop if nullif(trim(p->>required_field),'') is null then raise exception 'Field wajib: %',required_field; end if; end loop;
 elsif p_kind='target' then
  if p->>'fiscal_year' is null or p->>'annual_target' is null or jsonb_typeof(p->'allocations') is distinct from 'array' then raise exception 'Tahun, target dan array alokasi wajib.'; end if;
 elsif p_kind='funds' then
  if nullif(p->>'as_of','') is null or p->>'operating_target' is null or jsonb_typeof(p->'buckets') is distinct from 'array' then raise exception 'Tanggal dan target/bucket reserve wajib.'; end if;
  perform (p->>'as_of')::date;
 elsif p_kind='budget' then
  foreach required_field in array array['project_id','service_line_key','contract_value','budgeted_hpp','committed_cost'] loop if nullif(trim(p->>required_field),'') is null then raise exception 'Field wajib: %',required_field; end if; end loop;
 elsif p_kind='reversal' then
  if p->>'date' is null or p->>'journal_id' is null then raise exception 'Tanggal dan jurnal sumber wajib.'; end if;
 end if;
 foreach required_field in array array['amount','quantity','unit_price','discount','tax','management_fee','other_fees','annual_target','forecast','operating_target','contract_value','budgeted_hpp','committed_cost','approval_threshold'] loop
 if p->>required_field is not null and (p->>required_field)::numeric::text in ('NaN','Infinity','-Infinity') then raise exception 'Angka tidak finite: %',required_field; end if;
 end loop;
 if p_kind='account' then
 if nullif(trim(p->>'code'),'') is null or exists(select 1 from finance_pilot_dev.finance_coa where code=p->>'code') or nullif(trim(p->>'name'),'') is null or p->>'account_class' not in ('Aset','Kewajiban','Ekuitas','Pendapatan','Beban Operasional','Beban Langsung Proyek','Beban Non-Operasional','Pajak') or p->>'cash_flow_category' not in ('Operasional','Investasi','Pendanaan','Non-Kas') then raise exception 'Akun baru dan klasifikasi valid wajib.'; end if; return 0; end if;
 if p_kind='policy' then perform finance_pilot_dev_private.validate_policy(p); return 0; end if;
 if p_kind in ('journal','invoice','receipt','reversal') then
  perform finance_pilot_dev_private.evidence(p->>'evidence_path');
  perform finance_pilot_dev_private.lock_period((p->>'date')::date);
 end if;
 if p_kind in ('journal','invoice','receipt','target','funds','budget','reversal') and finance_pilot_dev_private.policy() is null then raise exception 'Kebijakan belum disetujui CEO; jangan memakai asumsi.'; end if;
 if p_kind='journal' then
  if p->>'claim_id' is not null and not exists(select 1 from finance_pilot_dev.finance_next_requests where id=(p->>'claim_id')::uuid and kind='claim' and state='approved' and (payload->>'amount')::numeric=(p->>'amount')::numeric and payload->>'evidence_path'=p->>'evidence_path') then raise exception 'Claim sumber tidak cocok atau belum ditriage.'; end if;
  if nullif(trim(p->>'reference'),'') is null then raise exception 'Referensi transaksi wajib.'; end if;
  if jsonb_typeof(p->'lines')<>'array' or jsonb_array_length(p->'lines')<2 then raise exception 'Minimal dua baris.'; end if;
  select sum(coalesce((value->>'debit')::numeric,0)),sum(coalesce((value->>'credit')::numeric,0)) into amount,total from jsonb_array_elements(p->'lines');
  if amount is null or amount<=0 or amount<>total then raise exception 'Jurnal tidak seimbang.'; end if;
  if p->>'business_event' not in ('customer_advance','project_expense','operating_expense','vendor_bill','vendor_payment','owner_receivable','asset_purchase','opening_adjustment','profit_distribution','manual') then raise exception 'Business event wajib.'; end if;
  if exists(select 1 from jsonb_array_elements(p->'lines') a where a->>'coa_code'=ac->>'distribution_payable') then raise exception 'Kebijakan distribusi dan eligible profit belum diputuskan; diblokir.'; end if;
  if p->>'business_event'='profit_distribution' then raise exception 'Kebijakan distribusi dan eligible profit belum diputuskan; diblokir.'; end if;
 elsif p_kind='invoice' then
  if nullif(trim(p->>'client'),'') is null or nullif(trim(p->>'item_description'),'') is null or (p->>'quantity')::numeric<=0 or (p->>'unit_price')::numeric<=0 then raise exception 'Client, item, kuantitas dan harga wajib.'; end if;
  if (p->>'due_date')::date<(p->>'date')::date then raise exception 'Jatuh tempo sebelum tanggal invoice.'; end if;
  if not exists(select 1 from finance_pilot_dev.finance_next_service_lines where service_line_key=p->>'service_line_key' and is_active) then raise exception 'Service line wajib.'; end if;
  if (p->>'tax')::numeric<0 or (p->>'discount')::numeric<0 or (p->>'management_fee')::numeric<0 or (p->>'other_fees')::numeric<0 then raise exception 'Komponen invoice tidak boleh negatif.'; end if;
  if nullif(trim(p->>'milestone_evidence'),'') is null then raise exception 'Bukti milestone selesai wajib sebelum pengakuan revenue.'; end if;
  amount:=round((p->>'quantity')::numeric*(p->>'unit_price')::numeric,2)-coalesce((p->>'discount')::numeric,0)+coalesce((p->>'tax')::numeric,0)+coalesce((p->>'management_fee')::numeric,0)+coalesce((p->>'other_fees')::numeric,0);
  if amount<=0 then raise exception 'Total invoice harus positif.'; end if;
  if (select sum(value::numeric) from jsonb_array_elements_text(p->'percentages')) is distinct from 100::numeric or exists(select 1 from jsonb_array_elements_text(p->'percentages') where value::numeric<=0) then raise exception 'Termin harus tepat 100%%.'; end if;
  pr:=nullif(p->>'project_id','')::uuid;
  if pr is not null and not exists(select 1 from finance_pilot_dev.finance_next_project_controls where project_id=pr and service_line_key=p->>'service_line_key' and financially_closed_at is null) then raise exception 'Project/service line belum memiliki budget disetujui.'; end if;
 elsif p_kind='receipt' then
  amount:=(p->>'amount')::numeric;
  if amount<=0 or nullif(trim(p->>'reference'),'') is null then raise exception 'Nominal dan referensi pembayaran wajib.'; end if;
  if p->>'deposit_coa_code' is distinct from ac->>'cash' then raise exception 'Akun kas harus mapping yang disetujui.'; end if;
  if not exists(select 1 from finance_pilot_dev.finance_documents where id=(p->>'invoice_id')::uuid and finance_pilot is true and document_type='invoice' and pilot_journal_id is not null and balance>=amount) then raise exception 'Invoice tidak ditemukan atau pembayaran melebihi saldo.'; end if;
 elsif p_kind='target' then
  if (p->>'fiscal_year')::int not between 2000 and 2200 or (p->>'annual_target')::numeric<=0 then raise exception 'Tahun/target tidak valid.'; end if;
  if jsonb_array_length(p->'allocations')<12 then raise exception 'Alokasi bulanan per service wajib.'; end if;
  select sum((value->>'amount')::numeric) into total from jsonb_array_elements(p->'allocations');
  if total is distinct from (p->>'annual_target')::numeric or exists(select 1 from jsonb_array_elements(p->'allocations') a where ((a->>'amount')::numeric<0 or (a->>'amount')::numeric::text in ('NaN','Infinity','-Infinity') or a->>'amount' is null) or (a->>'month')::int not between 1 and 12 or not exists(select 1 from finance_pilot_dev.finance_next_service_lines s where s.service_line_key=a->>'service_line_key')) then raise exception 'Alokasi bulanan/service tidak valid atau tidak sama dengan annual target.'; end if;
  if exists(select 1 from jsonb_array_elements(p->'allocations') a group by a->>'month',a->>'service_line_key' having count(*)>1) or (select count(distinct a->>'month') from jsonb_array_elements(p->'allocations') a)<>12 then raise exception 'Semua bulan wajib tanpa alokasi duplikat.'; end if;
 elsif p_kind='funds' then
  if (p->>'operating_target')::numeric<=0 then raise exception 'Target operating reserve wajib positif.'; end if;
  if jsonb_array_length(p->'buckets')<>3 or (select count(distinct a->>'key') from jsonb_array_elements(p->'buckets') a)<>3 or exists(select 1 from jsonb_array_elements(p->'buckets') a where a->>'key' not in ('project','operating','emergency') or (a->>'amount') is null or (a->>'amount')::numeric<0 or (a->>'amount')::numeric::text in ('NaN','Infinity','-Infinity')) then raise exception 'Bucket project, operating, emergency wajib tanpa duplikat.'; end if;
  -- Tax and distribution payable are ledger liabilities, not duplicate reserve balances.
 elsif p_kind='budget' then
  pr:=(p->>'project_id')::uuid;
  if not exists(select 1 from finance_pilot_dev.projects where id=pr and deleted_at is null) or not exists(select 1 from finance_pilot_dev.finance_next_service_lines where service_line_key=p->>'service_line_key') or (p->>'contract_value')::numeric<0 or (p->>'budgeted_hpp')::numeric<0 or (p->>'committed_cost')::numeric<0 then raise exception 'Project budget tidak valid.'; end if;
 elsif p_kind='reversal' then
  if not exists(select 1 from finance_pilot_dev.finance_next_journal_entries where id=(p->>'journal_id')::uuid and source_type in ('request','finance_document') and entry_date<=(p->>'date')::date) then raise exception 'Jurnal sumber tidak valid atau tanggal reversal sebelum sumber.'; end if;
  if exists(select 1 from finance_pilot_dev.finance_documents where pilot_journal_id=(p->>'journal_id')::uuid and document_type='invoice' and paid>0) then raise exception 'Balikkan receipt terlebih dahulu sebelum membalikkan invoice dibayar.'; end if;
 elsif p_kind='project_closure' then
  select * into ctl from finance_pilot_dev.finance_next_project_controls where project_id=(p->>'project_id')::uuid for update;
  if ctl.project_id is null or ctl.financially_closed_at is not null or nullif(p->>'handover_evidence','') is null then raise exception 'Project aktif dan bukti handover wajib.'; end if;
  if ctl.service_line_key='digital_system' and ctl.delivery_confirmed_at is null then raise exception 'Konfirmasi CTO wajib untuk project digital.'; end if;
 end if;
 if p_kind in ('target','funds','budget','reversal','project_closure','account') and nullif(trim(p->>'reason'),'') is null then raise exception 'Alasan wajib.'; end if;
 if coalesce(amount,0)::text in ('NaN','Infinity','-Infinity') then raise exception 'Nilai bukan angka finite.'; end if;
 return coalesce(amount,0);
end $$;

create or replace function finance_pilot_dev_private.over_budget(p_lines jsonb) returns boolean language sql stable security definer set search_path='' as $$
 select exists(
 select 1 from (
  select nullif(a->>'project_id','')::uuid project_id,
   sum(coalesce((a->>'debit')::numeric,0)-coalesce((a->>'credit')::numeric,0)) amount
  from jsonb_array_elements(p_lines) a join finance_pilot_dev.finance_coa c on c.code=a->>'coa_code'
  where c.account_class='Beban Langsung Proyek'
  group by nullif(a->>'project_id','')::uuid
 ) cost join finance_pilot_dev.finance_next_project_controls pc on pc.project_id=cost.project_id
 where cost.amount+pc.committed_cost+(select coalesce(sum(l.debit-l.credit),0)
  from finance_pilot_dev.finance_next_journal_lines l join finance_pilot_dev.finance_coa ca on ca.code=l.coa_code
  where l.project_id=pc.project_id and ca.account_class='Beban Langsung Proyek')>pc.budgeted_hpp
 );
$$;
revoke all on function finance_pilot_dev_private.over_budget(jsonb) from public,anon,authenticated;

-- Outstanding vendor liability is calculated from the one posted ledger, including reversals.
create or replace function finance_pilot_dev_private.ap_balance(p_bill uuid,p_asof date) returns numeric language sql stable security definer set search_path='' as $$
 select coalesce(sum(l.credit-l.debit),0) from finance_pilot_dev.finance_next_journal_lines l
 join finance_pilot_dev.finance_next_journal_entries e on e.id=l.journal_entry_id
 left join finance_pilot_dev.finance_next_journal_entries original on original.id=e.reversal_of_id
 join finance_pilot_dev.finance_next_requests r on r.id::text=case when e.reversal_of_id is not null then original.source_id else e.source_id end
 where e.status='posted' and e.entry_date<=p_asof and l.coa_code=finance_pilot_dev_private.policy()->'accounts'->>'payable'
 and (case when e.reversal_of_id is not null then original.source_type else e.source_type end)='request'
 and (r.id=p_bill or (r.payload->>'business_event'='vendor_payment' and r.payload->>'vendor_bill_id'=p_bill::text));
$$;
revoke all on function finance_pilot_dev_private.ap_balance(uuid,date) from public,anon,authenticated;
create unique index finance_next_vendor_payment_reference on finance_pilot_dev.finance_next_requests
 ((payload->>'vendor_bill_id'),(payload->>'reference')) where kind='journal' and state='posted' and payload->>'business_event'='vendor_payment';

-- Submit decides only documented routine versus approval events. Unknown policy blocks posting.
create or replace function finance_pilot_dev.finance_pilot_submit(p_id uuid) returns text language plpgsql security definer set search_path='' as $$
declare r finance_pilot_dev.finance_next_requests%rowtype; amt numeric; gated boolean;
begin
 perform finance_pilot_dev_private.actor('manage');
 select * into r from finance_pilot_dev.finance_next_requests where id=p_id for update;
 if r.id is null or r.prepared_by<>finance_pilot_dev.current_membership_id() then raise exception 'Draft tidak ditemukan.'; end if;
 if r.state<>'draft' then return r.state; end if;
 amt:=finance_pilot_dev_private.validate(r.kind,r.payload);
 gated:=r.kind in ('target','policy','funds','budget','reversal','account') or (r.kind in ('journal','invoice','receipt') and amt>=(finance_pilot_dev_private.policy()->>'approval_threshold')::numeric) or (r.kind='journal' and r.payload->>'business_event' in ('owner_receivable','opening_adjustment','manual'));
 if r.kind='journal' and exists(select 1 from jsonb_array_elements(r.payload->'lines') a where a->>'coa_code' in (finance_pilot_dev_private.policy()->'accounts'->>'related_receivable',finance_pilot_dev_private.policy()->'accounts'->>'retained_earnings')) then gated:=true; end if;
 if r.kind='journal' and exists(select 1 from finance_pilot_dev.finance_next_requests x where x.id<>r.id and x.kind='journal' and x.state in ('submitted','approved','posted') and x.payload->>'reference'=r.payload->>'reference' and x.payload->>'date'=r.payload->>'date') then
 if nullif(trim(r.payload->>'duplicate_reason'),'') is null then raise exception 'Potential duplicate: referensi/tanggal sama. Catat alasan dan minta approval.'; end if; gated:=true; end if;
 -- Sum all cost lines for each project; splitting lines cannot bypass approval.
 if r.kind='journal' and finance_pilot_dev_private.over_budget(r.payload->'lines') then gated:=true; end if;
 update finance_pilot_dev.finance_next_requests set state=case when gated then 'submitted' else 'approved' end,submitted_at=now(),updated_at=now() where id=p_id;
 perform finance_pilot_dev_private.audit('request.submit',r.kind,p_id::text,to_jsonb(r),jsonb_build_object('gated',gated));
 if not gated then perform finance_pilot_dev.finance_pilot_execute(p_id); return 'posted'; end if;
 return 'submitted';
end $$;

create or replace function finance_pilot_dev.finance_pilot_review(p_id uuid,p_decision text,p_note text) returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=finance_pilot_dev_private.actor('approve'); r finance_pilot_dev.finance_next_requests%rowtype;
begin
 select * into r from finance_pilot_dev.finance_next_requests where id=p_id for update;
 if r.id is null then raise exception 'Request tidak ditemukan.'; end if;
 if r.approved_by=actor and r.state in ('approved','rejected','posted') then
 if ((r.state in ('approved','posted') and p_decision='approve') or (r.state='rejected' and p_decision='reject')) and r.review_note=p_note then return; end if;
 raise exception 'Keputusan approval immutable.'; end if;
 if r.kind in ('claim','estimate') then raise exception 'Pengajuan sumber ditriage COO, bukan approval finansial.'; end if;
 if r.state<>'submitted' or r.prepared_by=actor then raise exception 'Request tidak bisa diapprove atau self approval.' using errcode='42501'; end if;
 if p_decision not in ('approve','reject') or nullif(trim(p_note),'') is null then raise exception 'Keputusan dan komentar wajib.'; end if;
 update finance_pilot_dev.finance_next_requests set state=case p_decision when 'approve' then 'approved' else 'rejected' end,approved_by=actor,reviewed_at=now(),review_note=p_note,updated_at=now() where id=p_id;
 perform finance_pilot_dev_private.audit('request.'||p_decision,r.kind,p_id::text,to_jsonb(r),jsonb_build_object('approver',actor,'decision',p_decision),p_note);
 -- CEO only records approval. COO applies the approved request via execute().
end $$;

create or replace function finance_pilot_dev_private.number(p_type text) returns text language plpgsql security definer set search_path='' as $$
declare s finance_pilot_dev.finance_sequences%rowtype; per text:=to_char(now() at time zone 'Asia/Jakarta','YYYYMM'); num text;
begin
 select * into s from finance_pilot_dev.finance_sequences where document_type=p_type for update;
 if s.document_type is null then raise exception 'Sequence % belum tersedia.',p_type; end if;
 if s.period_key<>per then s.last_number:=0; end if;
 loop
 s.last_number:=s.last_number+1; num:=s.prefix||'-'||per||'-'||lpad(s.last_number::text,4,'0');
 exit when not exists(select 1 from finance_pilot_dev.finance_documents where document_number=num);
 end loop;
 update finance_pilot_dev.finance_sequences set period_key=per,last_number=s.last_number,updated_at=now() where document_type=p_type;
 return num;
end $$;

create or replace function finance_pilot_dev.finance_pilot_execute(p_id uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=finance_pilot_dev_private.actor('manage'); r finance_pilot_dev.finance_next_requests%rowtype; p jsonb; source_doc finance_pilot_dev.finance_documents%rowtype; ac jsonb:=finance_pilot_dev_private.policy()->'accounts'; eid uuid; did uuid; n text; amt numeric(18,2); sub numeric(18,2); rev numeric(18,2); tax numeric(18,2); ls jsonb; inv finance_pilot_dev.finance_documents%rowtype; sk text; pc finance_pilot_dev.finance_next_project_controls%rowtype;
begin
 select * into r from finance_pilot_dev.finance_next_requests where id=p_id for update;
 if r.id is null then raise exception 'Request tidak ditemukan.'; end if;
 if r.state='posted' then return r.result_id; end if;
 if r.kind in ('claim','estimate') then raise exception 'Pengajuan sumber wajib ditautkan ke transaksi/budget, bukan diterapkan langsung.'; end if;
 if r.state<>'approved' then raise exception 'Request belum disetujui.'; end if;
 p:=r.payload; amt:=finance_pilot_dev_private.validate(r.kind,p);
 if r.kind in ('journal','invoice','receipt') and amt>=(finance_pilot_dev_private.policy()->>'approval_threshold')::numeric and r.approved_by is null then raise exception 'Nominal mencapai threshold; diperlukan approval CEO.'; end if;
 if r.kind='account' then
 insert into finance_pilot_dev.finance_coa(code,name,account_class,cash_flow_category,default_flow,cost_nature,control_position,retained_earnings_impact) values(p->>'code',p->>'name',p->>'account_class',p->>'cash_flow_category','Non-Kas','Non-Beban','Normal','Tidak Langsung');
 elsif r.kind='journal' then
 if p->>'business_event'='vendor_payment' then
  perform 1 from finance_pilot_dev.finance_next_requests where id=(p->>'vendor_bill_id')::uuid for update;
  if p->'lines' is distinct from finance_pilot_dev_private.template(p) then raise exception 'Journal vendor payment tidak cocok sumber.'; end if;
 end if;
 -- Serialize project cost postings and budget revisions. Recheck after waiting.
 perform 1 from finance_pilot_dev.finance_next_project_controls where project_id in
 (select nullif(value->>'project_id','')::uuid from jsonb_array_elements(p->'lines')) order by project_id for update;
 if finance_pilot_dev_private.over_budget(p->'lines') and r.approved_by is null then
  raise exception 'Budget project berubah/terlampaui; diperlukan approval CEO.';
 end if;
 eid:=finance_pilot_dev_private.post((p->>'date')::date,p->>'description',p->'lines','request',r.id::text);
 if p->>'business_event'='asset_purchase' then
 insert into finance_pilot_dev.finance_assets(asset_code,asset_name,category,acquisition_date,acquisition_value,custodian,useful_life_months,created_by_membership_id,pilot_journal_id) values('AST-FP-'||r.id::text,p->>'asset_name',p->>'asset_class',(p->>'date')::date,(p->>'amount')::numeric,p->>'custodian',(p->>'useful_life_months')::int,actor,eid); end if;
 elsif r.kind='invoice' then
 sub:=round((p->>'quantity')::numeric*(p->>'unit_price')::numeric,2);
 tax:=coalesce((p->>'tax')::numeric,0); rev:=amt-tax;
 if rev<=0 then raise exception 'Revenue invoice harus positif.'; end if;
 select revenue_account_code into sk from finance_pilot_dev.finance_next_service_lines where service_line_key=p->>'service_line_key';
 if not exists(select 1 from finance_pilot_dev.finance_coa where code=sk and account_class='Pendapatan' and is_active) then raise exception 'Mapping revenue service line tidak valid.'; end if;
 n:=finance_pilot_dev_private.number('invoice'); did:=extensions.gen_random_uuid();
 ls:=jsonb_build_array(jsonb_build_object('coa_code',ac->>'receivable','debit',amt,'credit',0,'project_id',p->>'project_id','service_line_key',p->>'service_line_key','client',p->>'client'),jsonb_build_object('coa_code',sk,'debit',0,'credit',rev,'project_id',p->>'project_id','service_line_key',p->>'service_line_key','client',p->>'client'));
 if tax>0 then ls:=ls||jsonb_build_array(jsonb_build_object('coa_code',ac->>'tax_payable','debit',0,'credit',tax,'project_id',p->>'project_id','service_line_key',p->>'service_line_key','client',p->>'client')); end if;
 eid:=finance_pilot_dev_private.post((p->>'date')::date,'Invoice '||n,ls,'finance_document',did::text);
 insert into finance_pilot_dev.finance_documents(id,document_type,document_number,document_date,due_date,client,client_address,project_name,status,subtotal,discount,tax,total,paid,balance,notes,items,created_by_membership_id,updated_by_membership_id,gross_total,management_fee,other_fees,installment_scheme,payment_schedule,finance_pilot,pilot_project_id,pilot_service_line_key,pilot_journal_id,pilot_evidence_path)
 values(did,'invoice',n,(p->>'date')::date,(p->>'due_date')::date,p->>'client',p->>'client_address',(select name from finance_pilot_dev.projects where id=nullif(p->>'project_id','')::uuid),'Unpaid',sub,(p->>'discount')::numeric,tax,amt,0,amt,p->>'notes',jsonb_build_array(jsonb_build_object('description',p->>'item_description','quantity',(p->>'quantity')::numeric,'unit_price',(p->>'unit_price')::numeric)),actor,actor,amt,(p->>'management_fee')::numeric,(p->>'other_fees')::numeric,p->>'installment_scheme',p->'percentages',true,nullif(p->>'project_id','')::uuid,p->>'service_line_key',eid,p->>'evidence_path');
 elsif r.kind='receipt' then
 select * into inv from finance_pilot_dev.finance_documents where id=(p->>'invoice_id')::uuid for update;
 -- Lock invoice before rechecking outstanding, and deduplicate real payment reference, not only request key.
 if amt>inv.balance then raise exception 'Pembayaran melebihi saldo terbaru.'; end if;
 if exists(select 1 from finance_pilot_dev.finance_documents where finance_pilot is true and document_type='receipt' and linked_invoice_id=inv.id and reference_number=p->>'reference') then raise exception 'Referensi pembayaran sudah digunakan.' using errcode='23505'; end if;
 n:=finance_pilot_dev_private.number('receipt'); did:=extensions.gen_random_uuid();
 ls:=jsonb_build_array(jsonb_build_object('coa_code',ac->>'cash','debit',amt,'credit',0,'project_id',inv.pilot_project_id,'service_line_key',inv.pilot_service_line_key,'client',inv.client),jsonb_build_object('coa_code',ac->>'receivable','debit',0,'credit',amt,'project_id',inv.pilot_project_id,'service_line_key',inv.pilot_service_line_key,'client',inv.client));
 eid:=finance_pilot_dev_private.post((p->>'date')::date,'Receipt '||n,ls,'finance_document',did::text);
 insert into finance_pilot_dev.finance_documents(id,document_type,document_number,document_date,client,project_name,status,subtotal,total,paid,balance,reference_number,linked_invoice_id,items,created_by_membership_id,updated_by_membership_id,finance_pilot,pilot_project_id,pilot_service_line_key,pilot_journal_id,pilot_deposit_coa_code,pilot_evidence_path)
 values(did,'receipt',n,(p->>'date')::date,inv.client,inv.project_name,'Paid',amt,amt,amt,0,p->>'reference',inv.id,'[]',actor,actor,true,inv.pilot_project_id,inv.pilot_service_line_key,eid,ac->>'cash',p->>'evidence_path');
 update finance_pilot_dev.finance_documents set paid=paid+amt,balance=balance-amt,status=case when balance-amt=0 then 'Paid' else 'Partially Paid' end,updated_at=now(),updated_by_membership_id=actor where id=inv.id;
 elsif r.kind='budget' then
 select * into pc from finance_pilot_dev.finance_next_project_controls where project_id=(p->>'project_id')::uuid for update;
 if pc.project_id is not null and pc.service_line_key<>p->>'service_line_key' and exists(select 1 from finance_pilot_dev.finance_next_journal_lines where project_id=pc.project_id) then raise exception 'Service line project posted tidak boleh diganti.'; end if;
 insert into finance_pilot_dev.finance_next_project_controls(project_id,service_line_key,contract_value,budgeted_hpp,committed_cost,approved_request_id)
 values((p->>'project_id')::uuid,p->>'service_line_key',(p->>'contract_value')::numeric,(p->>'budgeted_hpp')::numeric,(p->>'committed_cost')::numeric,p_id)
 on conflict(project_id) do update set service_line_key=excluded.service_line_key,contract_value=excluded.contract_value,budgeted_hpp=excluded.budgeted_hpp,committed_cost=excluded.committed_cost,approved_request_id=p_id;
 elsif r.kind='project_closure' then
 if exists(select 1 from finance_pilot_dev.finance_documents d where finance_pilot is true and pilot_project_id=(p->>'project_id')::uuid and document_type='invoice' and balance>0 and not exists(select 1 from finance_pilot_dev.finance_next_journal_entries re where re.reversal_of_id=d.pilot_journal_id)) then raise exception 'Project masih memiliki piutang; closure memerlukan penyelesaian atau write-off disetujui.'; end if;
 if exists(select 1 from finance_pilot_dev.finance_next_requests bill where bill.kind='journal' and bill.state='posted' and bill.payload->>'project_id'=p->>'project_id' and bill.payload->>'business_event'<>'vendor_payment' and finance_pilot_dev_private.ap_balance(bill.id,'9999-12-31'::date)>0) then raise exception 'Project masih memiliki outstanding vendor AP.'; end if;
 update finance_pilot_dev.finance_next_project_controls set handover_evidence=p->>'handover_evidence',financially_closed_at=now(),financially_closed_by=actor where project_id=(p->>'project_id')::uuid;
 elsif r.kind='reversal' then
 perform 1 from finance_pilot_dev.finance_next_requests bill where bill.id in (
  select case when rq.payload->>'business_event'='vendor_payment' then (rq.payload->>'vendor_bill_id')::uuid else rq.id end
  from finance_pilot_dev.finance_next_journal_entries source join finance_pilot_dev.finance_next_requests rq on source.source_type='request' and rq.id::text=source.source_id where source.id=(p->>'journal_id')::uuid
 ) order by bill.id for update;
 if exists(select 1 from finance_pilot_dev.finance_next_journal_entries source join finance_pilot_dev.finance_next_requests bill on bill.id::text=source.source_id and source.source_type='request'
  join finance_pilot_dev.finance_next_requests payment on payment.payload->>'vendor_bill_id'=bill.id::text and payment.payload->>'business_event'='vendor_payment' and payment.state='posted'
  join finance_pilot_dev.finance_next_journal_entries pe on pe.id=payment.result_id
  where source.id=(p->>'journal_id')::uuid and not exists(select 1 from finance_pilot_dev.finance_next_journal_entries re where re.reversal_of_id=pe.id)) then raise exception 'Balikkan pembayaran vendor dahulu sebelum bill.'; end if;
 if exists(select 1 from finance_pilot_dev.finance_next_journal_entries where reversal_of_id=(p->>'journal_id')::uuid) then raise exception 'Jurnal sudah dibalik.'; end if;
 select jsonb_agg(jsonb_build_object('coa_code',coa_code,'description',description,'debit',credit,'credit',debit,'project_id',project_id,'service_line_key',service_line_key,'client',client) order by line_number) into ls from finance_pilot_dev.finance_next_journal_lines where journal_entry_id=(p->>'journal_id')::uuid;
 eid:=finance_pilot_dev_private.post((p->>'date')::date,'Reversal: '||(p->>'reason'),ls,'reversal',r.id::text,(p->>'journal_id')::uuid);
 select * into source_doc from finance_pilot_dev.finance_documents where pilot_journal_id=(p->>'journal_id')::uuid for update;
 if source_doc.id is not null then
  update finance_pilot_dev.finance_documents set status='Void',updated_at=now(),updated_by_membership_id=actor where id=source_doc.id;
  if source_doc.document_type='receipt' then
    update finance_pilot_dev.finance_documents set paid=paid-source_doc.total,balance=balance+source_doc.total,status=case when paid-source_doc.total=0 then 'Unpaid' else 'Partially Paid' end,updated_at=now(),updated_by_membership_id=actor where id=source_doc.linked_invoice_id;
  end if;
 end if;
 end if;
 -- Targets/policies/funds are versioned immutable request snapshots; never maintain a second balance.
 if r.kind='journal' and p->>'claim_id' is not null then update finance_pilot_dev.finance_next_requests set state='posted',result_id=eid,updated_at=now() where id=(p->>'claim_id')::uuid and kind='claim'; end if;
 update finance_pilot_dev.finance_next_requests set state='posted',result_id=coalesce(did,eid,r.id),updated_at=now() where id=p_id;
 perform finance_pilot_dev_private.audit('request.apply',r.kind,p_id::text,to_jsonb(r),jsonb_build_object('result_id',coalesce(did,eid,r.id)));
 return coalesce(did,eid,r.id);
end $$;

-- Period wrappers retain existing signatures while enforcing PRD position and shared posting lock.
create or replace function finance_pilot_dev.finance_next_request_period_change(p_period_month date,p_action text,p_reason text)
returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=finance_pilot_dev_private.actor('manage'); s text;
begin
 if p_period_month is null or p_period_month<>date_trunc('month',p_period_month)::date or p_action not in ('close','reopen') or nullif(trim(p_reason),'') is null then raise exception 'Bulan, aksi dan alasan wajib.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('finance-dev-period:'||p_period_month::text,0));
 select status into s from finance_pilot_dev.finance_next_periods where period_month=p_period_month for update;
 if (p_action='close' and coalesce(s,'open')<>'open') or (p_action='reopen' and s is distinct from 'closed') then raise exception 'Status periode tidak sesuai.'; end if;
 insert into finance_pilot_dev.finance_next_periods(period_month,status,requested_action,requested_by_membership_id,requested_at,review_note)
 values(p_period_month,case p_action when 'close' then 'close_requested' else 'reopen_requested' end,p_action,actor,now(),p_reason)
 on conflict(period_month) do update set status=excluded.status,requested_action=p_action,requested_by_membership_id=actor,requested_at=now(),reviewed_at=null,reviewed_by_membership_id=null,review_note=p_reason,updated_at=now();
 perform finance_pilot_dev_private.audit('period.request','period',p_period_month::text,null,jsonb_build_object('action',p_action),p_reason);
end $$;
create or replace function finance_pilot_dev.finance_next_review_period_change(p_period_month date,p_decision text,p_note text)
returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=finance_pilot_dev_private.actor('approve'); r finance_pilot_dev.finance_next_periods%rowtype; s text;
begin
 perform pg_advisory_xact_lock(hashtextextended('finance-dev-period:'||p_period_month::text,0));
 select * into r from finance_pilot_dev.finance_next_periods where period_month=p_period_month for update;
 if r.period_month is null or r.status not in ('close_requested','reopen_requested') or r.requested_by_membership_id=actor then raise exception 'Permintaan tidak valid atau self approval.'; end if;
 if p_decision not in ('approve','reject') or nullif(trim(p_note),'') is null then raise exception 'Keputusan dan komentar wajib.'; end if;
 s:=case when p_decision='approve' then case r.requested_action when 'close' then 'closed' else 'open' end else case r.requested_action when 'close' then 'open' else 'closed' end end;
 update finance_pilot_dev.finance_next_periods set status=s,reviewed_by_membership_id=actor,reviewed_at=now(),review_note=p_note,updated_at=now() where period_month=p_period_month;
 perform finance_pilot_dev_private.audit('period.'||p_decision,'period',p_period_month::text,to_jsonb(r),jsonb_build_object('status',s),p_note);
end $$;

-- CTO access is limited to assigned digital delivery confirmation; no finance journal rights.
create or replace function finance_pilot_dev.finance_pilot_confirm_delivery(p_project_id uuid,p_evidence text) returns void
language plpgsql security definer set search_path='' as $$
declare actor uuid:=finance_pilot_dev.current_membership_id(); pk text;
begin
 select p.key into pk from finance_pilot_dev.memberships m join finance_pilot_dev.positions p on p.id=m.position_id where m.id=actor;
 if pk is distinct from 'cto' or not exists(select 1 from finance_pilot_dev.project_members where project_id=p_project_id and membership_id=actor) then raise exception 'Hanya CTO yang ditugaskan.' using errcode='42501'; end if;
 if nullif(trim(p_evidence),'') is null then raise exception 'Bukti delivery wajib.'; end if;
 update finance_pilot_dev.finance_next_project_controls set delivery_confirmed_at=now(),delivery_confirmed_by=actor,handover_evidence=p_evidence where project_id=p_project_id and service_line_key='digital_system' and financially_closed_at is null;
 if not found then raise exception 'Project digital aktif tidak ditemukan.'; end if;
 perform finance_pilot_dev_private.audit('delivery.confirm','project',p_project_id::text,null,jsonb_build_object('evidence',p_evidence));
end $$;

create or replace function finance_pilot_dev.finance_pilot_reconcile(p_key uuid,p_asof date,p_balance numeric,p_evidence text) returns uuid
language plpgsql security definer set search_path='' as $$
declare actor uuid:=finance_pilot_dev_private.actor('manage'); ac text:=finance_pilot_dev_private.policy()->'accounts'->>'cash'; b numeric(18,2); fp text; rid uuid;
begin
 if p_key is null or p_asof is null or p_balance is null or ac is null then raise exception 'Rekonsiliasi memerlukan policy dan input lengkap.'; end if;
 perform finance_pilot_dev_private.evidence(p_evidence);
 perform pg_advisory_xact_lock(hashtextextended('finance-reconcile:'||ac||':'||p_asof::text,0));
 select id into rid from finance_pilot_dev.finance_next_reconciliations where request_key=p_key;
 if rid is not null then
 if not exists(select 1 from finance_pilot_dev.finance_next_reconciliations where id=rid and as_of_date=p_asof and statement_balance=p_balance and evidence_path=p_evidence) then raise exception 'Request key digunakan untuk rekonsiliasi berbeda.'; end if;
 return rid; end if;
 select coalesce(sum(l.debit-l.credit),0),md5(coalesce(string_agg(l.id::text,',' order by l.id),'')) into b,fp from finance_pilot_dev.finance_next_journal_lines l join finance_pilot_dev.finance_next_journal_entries e on e.id=l.journal_entry_id where l.coa_code=ac and e.entry_date<=p_asof;
 if p_balance<>b then raise exception 'Selisih bank % belum diselesaikan. Tidak ada auto adjustment.',p_balance-b; end if;
 insert into finance_pilot_dev.finance_next_reconciliations(request_key,bank_coa_code,as_of_date,statement_balance,book_balance,ledger_fingerprint,evidence_path,prepared_by) values(p_key,ac,p_asof,p_balance,b,fp,p_evidence,actor) returning id into rid;
 perform finance_pilot_dev_private.audit('bank.reconcile','reconciliation',rid::text,null,jsonb_build_object('as_of',p_asof,'book',b,'statement',p_balance));
 return rid;
end $$;

-- Append-only export audit; backend computes the same snapshot for audit/filter consistency.
create or replace function finance_pilot_dev.finance_pilot_audit_export(p_filters jsonb) returns void language plpgsql security definer set search_path='' as $$
begin perform finance_pilot_dev_private.actor('view'); perform finance_pilot_dev_private.audit('report.export','report',null,null,p_filters); end $$;

-- Explicit grants are necessary on current Supabase Data API defaults.
revoke all on all functions in schema finance_pilot_dev_private from public,anon,authenticated;
grant execute on function finance_pilot_dev_private.can_view() to authenticated;
do $$ declare f record; begin
 for f in select p.oid::regprocedure sig from pg_proc p where p.pronamespace='finance_pilot_dev'::regnamespace and p.proname like 'finance_pilot_%' loop
 execute format('revoke all on function %s from public,anon',f.sig);
 execute format('grant execute on function %s to authenticated',f.sig);
 end loop;
end $$;

create or replace function finance_pilot_dev_private.template(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb:=finance_pilot_dev_private.policy()->'accounts'; ev text:=p->>'business_event'; d text; c text; amt numeric(18,2):=(p->>'amount')::numeric; cl text; sk text; pr uuid:=nullif(p->>'project_id','')::uuid; bill finance_pilot_dev.finance_next_requests%rowtype; remaining numeric;
begin
 if ev in ('manual','opening_adjustment') then return p->'lines'; end if;
 if amt is null or amt<=0 or amt::text in ('NaN','Infinity','-Infinity') then raise exception 'Nominal business event harus positif.'; end if;
 if ev='vendor_payment' then
  if nullif(p->>'vendor_bill_id','') is null then raise exception 'Sumber vendor bill wajib.'; end if;
  select * into bill from finance_pilot_dev.finance_next_requests where id=(p->>'vendor_bill_id')::uuid and kind='journal' and state='posted';
  if bill.id is null or bill.payload->>'business_event'='vendor_payment' or not exists(select 1 from finance_pilot_dev.finance_next_journal_lines where journal_entry_id=bill.result_id and coa_code=a->>'payable' and credit>0) then raise exception 'Sumber AP posted tidak ditemukan.'; end if;
  if p->>'date' is null or (p->>'date')::date<(bill.payload->>'date')::date then raise exception 'Tanggal payment harus setelah atau sama dengan bill.'; end if;
  remaining:=least(finance_pilot_dev_private.ap_balance(bill.id,(p->>'date')::date),finance_pilot_dev_private.ap_balance(bill.id,'9999-12-31'::date));
  if amt>remaining then raise exception 'Payment melebihi outstanding vendor %.',remaining; end if;
  if p->>'client' is distinct from bill.payload->>'client' or nullif(p->>'project_id','') is distinct from nullif(bill.payload->>'project_id','') then raise exception 'Vendor/project harus cocok bill sumber.'; end if;
  d:=a->>'payable'; c:=a->>'cash';
 elsif ev='customer_advance' then d:=a->>'cash';c:=a->>'advance';
 elsif ev='owner_receivable' then d:=a->>'related_receivable';c:=a->>'cash';
   if nullif(trim(p->>'client'),'') is null or p->>'due_date' is null then raise exception 'Owner dan due date wajib untuk piutang pihak terkait.'; end if;
 elsif ev='asset_purchase' then d:=a->>'fixed_asset';c:=p->>'settlement_account';
   if nullif(trim(p->>'asset_name'),'') is null or coalesce((p->>'useful_life_months')::int,0)<=0 or nullif(trim(p->>'custodian'),'') is null then raise exception 'Nama aset, umur manfaat dan custodian wajib.'; end if;
 elsif ev in ('project_expense','operating_expense','vendor_bill') then
   d:=p->>'expense_account'; c:=case when ev='vendor_bill' then a->>'payable' else p->>'settlement_account' end;
   select account_class into cl from finance_pilot_dev.finance_coa where code=d and is_active;
   if (ev='project_expense' and cl is distinct from 'Beban Langsung Proyek') or (ev='operating_expense' and cl is distinct from 'Beban Operasional') or (ev='vendor_bill' and cl not in ('Beban Langsung Proyek','Beban Operasional')) then raise exception 'Akun expense tidak sesuai business event.'; end if;
 else raise exception 'Business event belum didukung.'; end if;
 if c is null or (ev in ('project_expense','operating_expense','vendor_bill','asset_purchase') and c not in (a->>'cash',a->>'payable')) or d is null then raise exception 'Mapping settlement tidak valid.'; end if;
 if c=a->>'payable' and (nullif(trim(p->>'client'),'') is null or nullif(p->>'due_date','') is null) then raise exception 'Vendor dan jatuh tempo wajib untuk AP.'; end if;
 if c=a->>'payable' and (p->>'due_date')::date<(p->>'date')::date then raise exception 'Jatuh tempo vendor sebelum tanggal bill.'; end if;
 if pr is not null then select service_line_key into sk from finance_pilot_dev.finance_next_project_controls where project_id=pr; end if;
 if ev in ('project_expense','customer_advance') and pr is null then raise exception 'Project wajib untuk advance/biaya langsung.'; end if;
 return jsonb_build_array(jsonb_build_object('coa_code',d,'description',p->>'description','debit',amt,'credit',0,'project_id',pr,'service_line_key',sk,'client',p->>'client'),jsonb_build_object('coa_code',c,'description',p->>'description','debit',0,'credit',amt,'project_id',pr,'service_line_key',sk,'client',p->>'client'));
end $$;
revoke all on function finance_pilot_dev_private.template(jsonb) from public,anon,authenticated;
create or replace function finance_pilot_dev.finance_pilot_journal_preview(p_payload jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin perform finance_pilot_dev_private.actor('manage'); return finance_pilot_dev_private.template(p_payload); end $$;
revoke all on function finance_pilot_dev.finance_pilot_journal_preview(jsonb) from public,anon;
grant execute on function finance_pilot_dev.finance_pilot_journal_preview(jsonb) to authenticated;
-- Asset inventory remains the existing canonical register, linked back to the source journal.
alter table finance_pilot_dev.finance_assets add column if not exists pilot_journal_id uuid references finance_pilot_dev.finance_next_journal_entries(id);

-- Snapshot uses decimal Postgres totals, the existing posted ledger and canonical documents.
-- All aggregates precede UI limits. No conversion of legacy cash transactions to accrual journals.
create or replace function finance_pilot_dev.finance_pilot_snapshot(
 p_view text default 'MTD',p_asof date default (now() at time zone 'Asia/Jakarta')::date,
 p_start date default null,p_end date default null,p_service text default null,p_project uuid default null,
 p_client text default null,p_compare text default 'Previous Period',p_payment text default null
) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare pol jsonb:=finance_pilot_dev_private.policy(); ac jsonb; v_start_date date; v_end_date date; v_fy_start date; v_fs int; v_fy int;
 v_cmp_start date; v_cmp_end date; result jsonb;
begin
 perform finance_pilot_dev_private.actor('view'); ac:=pol->'accounts'; v_fs:=(pol->>'fiscal_start')::int;
 if p_view not in ('MTD','QTD','YTD','Custom') or p_compare not in ('Previous Period','Previous Year','Budget','Target') or p_asof is null then raise exception 'Filter tidak valid.'; end if;
 v_end_date:=case when p_view='Custom' then p_end else p_asof end;
 p_asof:=v_end_date;
 if v_fs is not null then
 v_fy:=extract(year from p_asof)::int-case when extract(month from p_asof)<v_fs then 1 else 0 end;
 v_fy_start:=make_date(v_fy,v_fs,1);
 end if;
 v_start_date:=case p_view when 'MTD' then date_trunc('month',p_asof)::date
 when 'QTD' then case when v_fs is null then null else (v_fy_start+((floor(((extract(year from p_asof)-extract(year from v_fy_start))*12+extract(month from p_asof)-extract(month from v_fy_start))/3)*3)::int||' months')::interval)::date end
 when 'YTD' then v_fy_start else p_start end;
 if p_view='Custom' and (p_start is null or p_end is null or p_start>p_end) then raise exception 'Custom range wajib valid.'; end if;
 if p_service is not null and not exists(select 1 from finance_pilot_dev.finance_next_service_lines where service_line_key=p_service) then raise exception 'Service line tidak valid.'; end if;
 if p_compare='Previous Year' then v_cmp_start:=(v_start_date-interval '1 year')::date; v_cmp_end:=(v_end_date-interval '1 year')::date;
 elsif p_view='MTD' then v_cmp_start:=(v_start_date-interval '1 month')::date; v_cmp_end:=least((v_end_date-interval '1 month')::date,(v_start_date-interval '1 day')::date);
 elsif p_view='QTD' then v_cmp_start:=(v_start_date-interval '3 months')::date; v_cmp_end:=(v_end_date-interval '3 months')::date;
 elsif p_view='YTD' then v_cmp_start:=(v_start_date-interval '1 year')::date; v_cmp_end:=(v_end_date-interval '1 year')::date;
 else v_cmp_end:=v_start_date-1; v_cmp_start:=v_cmp_end-(v_end_date-v_start_date); end if;

 with
 all_lines as (
 select l.*,e.entry_date,e.description as entry_description,e.source_type,e.source_id,e.reversal_of_id,c.name as account_name,c.account_class,c.cash_flow_category,
 case when coalesce(r.payload->>'business_event',orig.payload->>'business_event')='vendor_payment' then (select bill.payload->>'business_event' from finance_pilot_dev.finance_next_requests bill where bill.id::text=coalesce(r.payload->>'vendor_bill_id',orig.payload->>'vendor_bill_id'))
 else coalesce(r.payload->>'business_event',orig.payload->>'business_event',case when coalesce(d.document_type,od.document_type)='receipt' then 'customer_receipt' when coalesce(d.document_type,od.document_type)='invoice' then 'client_invoice' end) end as business_event
 from finance_pilot_dev.finance_next_journal_lines l join finance_pilot_dev.finance_next_journal_entries e on e.id=l.journal_entry_id
 join finance_pilot_dev.finance_coa c on c.code=l.coa_code
 left join finance_pilot_dev.finance_next_requests r on r.id::text=e.source_id and e.source_type='request'
 left join finance_pilot_dev.finance_documents d on d.id::text=e.source_id and e.source_type='finance_document'
 left join finance_pilot_dev.finance_next_journal_entries oe on oe.id=e.reversal_of_id
 left join finance_pilot_dev.finance_documents od on od.id::text=oe.source_id and oe.source_type='finance_document'
 left join finance_pilot_dev.finance_next_requests orig on orig.id::text=oe.source_id and oe.source_type='request'
 where e.status='posted'
 ), dim as (
 select * from all_lines where (p_service is null or service_line_key=p_service) and (p_project is null or project_id=p_project) and (p_client is null or client=p_client)
 ), period_lines as (select * from dim where entry_date between v_start_date and v_end_date),
 income as (
 select coalesce(sum(credit-debit) filter(where account_class='Pendapatan'),0) as revenue,
 coalesce(sum(debit-credit) filter(where account_class='Beban Langsung Proyek'),0) as hpp,
 coalesce(sum(debit-credit) filter(where account_class='Beban Operasional'),0) as opex,
 coalesce(sum(debit-credit) filter(where account_class='Beban Non-Operasional'),0) as other,
 coalesce(sum(debit-credit) filter(where account_class='Pajak'),0) as tax from period_lines
 ), prior as (
 select coalesce(sum(credit-debit) filter(where account_class='Pendapatan'),0) as revenue,
 coalesce(sum(debit-credit) filter(where account_class='Beban Langsung Proyek'),0) as hpp,
 coalesce(sum(debit-credit) filter(where account_class='Beban Operasional'),0) as opex from dim where entry_date between v_cmp_start and v_cmp_end
 ), balances as (
 select c.code,c.name,c.account_class,coalesce(sum(d.debit-d.credit) filter(where d.entry_date<v_start_date),0) as opening,
 coalesce(sum(d.debit) filter(where d.entry_date between v_start_date and v_end_date),0) as debit,
 coalesce(sum(d.credit) filter(where d.entry_date between v_start_date and v_end_date),0) as credit,
 coalesce(sum(d.debit-d.credit) filter(where d.entry_date<=v_end_date),0) as closing
 from finance_pilot_dev.finance_coa c left join dim d on d.coa_code=c.code where c.is_active and c.account_class not like 'Kontrol%' group by c.code,c.name,c.account_class
 ), liquidity as (
 select coalesce(sum(debit-credit) filter(where coa_code=ac->>'cash'),0) as book_cash,
 coalesce(sum(credit-debit) filter(where coa_code=ac->>'payable'),0) as payables,
 coalesce(sum(credit-debit) filter(where coa_code=ac->>'tax_payable'),0) as taxes,
 coalesce(sum(credit-debit) filter(where coa_code=ac->>'distribution_payable'),0) as distribution,
 md5(coalesce(string_agg(id::text,',' order by id) filter(where coa_code=ac->>'cash'),'')) as fingerprint
 from all_lines where entry_date<=v_end_date
 ), recon as (
 select r.* from finance_pilot_dev.finance_next_reconciliations r where r.bank_coa_code=ac->>'cash' and r.as_of_date=v_end_date order by r.created_at desc limit 1
 ), fund_plan as (
 select payload from finance_pilot_dev.finance_next_requests where kind='funds' and state='posted' and (payload->>'as_of')::date<=v_end_date order by (payload->>'as_of')::date desc,reviewed_at desc limit 1
 ), buckets as (
 select value->>'key' as key,value->>'label' as label,(value->>'amount')::numeric as amount,true as restricted from fund_plan,jsonb_array_elements(payload->'buckets')
 ), inv as (
 select d.*,coalesce((select sum(r.total) from finance_pilot_dev.finance_documents r where r.finance_pilot is true and r.document_type='receipt' and r.linked_invoice_id=d.id and r.document_date<=v_end_date and r.pilot_journal_id is not null and not exists(select 1 from finance_pilot_dev.finance_next_journal_entries re where re.reversal_of_id=r.pilot_journal_id and re.entry_date<=v_end_date)),0) as asof_paid
 from finance_pilot_dev.finance_documents d where d.finance_pilot is true and d.document_type='invoice' and d.pilot_journal_id is not null and d.document_date<=v_end_date and not exists(select 1 from finance_pilot_dev.finance_next_journal_entries re where re.reversal_of_id=d.pilot_journal_id and re.entry_date<=v_end_date)
 and (p_service is null or d.pilot_service_line_key=p_service) and (p_project is null or d.pilot_project_id=p_project) and (p_client is null or d.client=p_client)
 ), invoice_rows as (
 select *,total-asof_paid as asof_balance,case when asof_paid=total then 'paid' when due_date<v_end_date then 'overdue' when asof_paid>0 then 'partially_paid' else 'issued' end as asof_status from inv
 ), selected_invoices as (select * from invoice_rows where p_payment is null or asof_status=p_payment),
 rec as (
 select r.* from finance_pilot_dev.finance_documents r join selected_invoices i on i.id=r.linked_invoice_id where r.finance_pilot is true and r.document_type='receipt' and r.pilot_journal_id is not null and r.document_date between v_start_date and v_end_date and not exists(select 1 from finance_pilot_dev.finance_next_journal_entries re where re.reversal_of_id=r.pilot_journal_id and re.entry_date<=v_end_date)
 ), vendor_bills_all as (
 select rq.id,rq.payload->>'reference' as reference,rq.payload->>'client' as vendor,(rq.payload->>'date')::date as bill_date,
 (rq.payload->>'due_date')::date as due_date,nullif(rq.payload->>'project_id','')::uuid as project_id,
 (select service_line_key from finance_pilot_dev.finance_next_project_controls where project_id=nullif(rq.payload->>'project_id','')::uuid) as service_line_key,
 rq.result_id as journal_id,rq.payload->>'evidence_path' as evidence_path,
 (select sum(l.credit-l.debit) from finance_pilot_dev.finance_next_journal_lines l where l.journal_entry_id=rq.result_id and l.coa_code=ac->>'payable') as amount,
 finance_pilot_dev_private.ap_balance(rq.id,v_end_date) as balance
 from finance_pilot_dev.finance_next_requests rq where rq.kind='journal' and rq.state='posted' and rq.payload->>'business_event'<>'vendor_payment'
 and (rq.payload->>'date')::date<=v_end_date and exists(select 1 from finance_pilot_dev.finance_next_journal_lines where journal_entry_id=rq.result_id and coa_code=ac->>'payable' and credit>0)
 ), vendor_bills as (
 select * from vendor_bills_all where (p_service is null or service_line_key=p_service) and (p_project is null or project_id=p_project) and (p_client is null or vendor=p_client)
 ), target as (
 select r.* from finance_pilot_dev.finance_next_requests r where r.kind='target' and r.state='posted' and (r.payload->>'fiscal_year')::int=v_fy order by reviewed_at desc,id limit 1
 ), original_target as (
 select payload from finance_pilot_dev.finance_next_requests where kind='target' and state='posted' and (payload->>'fiscal_year')::int=v_fy order by reviewed_at,id limit 1
 ), monthly as (
 select month,coalesce((select sum((a->>'amount')::numeric) from target,jsonb_array_elements(payload->'allocations') a where (a->>'month')::int=month and (p_service is null or a->>'service_line_key'=p_service)),0) as target,
 coalesce((select sum(credit-debit) from dim where account_class='Pendapatan' and entry_date>=(v_fy_start+((month-1)||' months')::interval)::date and entry_date<(v_fy_start+(month||' months')::interval)::date and entry_date<=p_asof),0) as actual
 from generate_series(1,12) month
 ), outcome as (
 select l.id,l.lead_code,l.account_name,l.stage,l.business_unit,l.lead_source,l.proposal_value,l.won_value,l.win_loss_reason,l.won_at,l.lost_at,l.proposal_date,ct.project_id,
 case when l.stage='Won' then (l.won_at at time zone 'Asia/Jakarta')::date when l.stage='Lost' then (l.lost_at at time zone 'Asia/Jakarta')::date else l.proposal_date end as outcome_date,
 s.service_line_key
 from finance_pilot_dev.pipeline_leads l left join finance_pilot_dev.finance_next_service_lines s on s.label=l.business_unit
 left join lateral(select project_id from finance_pilot_dev.commercial_tickets where pipeline_lead_id=l.id order by created_at desc limit 1) ct on true
 where l.stage in ('Proposal','Proposal / Offer','Decision','Proposal Sent','Submitted','Negotiation','Won','Lost','On Hold','Cancelled')
 ), selected_outcome as (
 select * from outcome where outcome_date between v_start_date and v_end_date and (p_service is null or service_line_key=p_service) and (p_project is null or project_id=p_project) and (p_client is null or account_name=p_client)
 ), service_stats as (
 select s.service_line_key,s.label,coalesce(sum(d.credit-d.debit) filter(where d.account_class='Pendapatan'),0) as revenue,coalesce(sum(d.debit-d.credit) filter(where d.account_class='Beban Langsung Proyek'),0) as hpp
 from finance_pilot_dev.finance_next_service_lines s left join period_lines d on d.service_line_key=s.service_line_key group by s.service_line_key,s.label
 ), journal_rows as (
 select e.*, (select jsonb_agg(jsonb_build_object('line_number',l.line_number,'coa_code',l.coa_code,'description',l.description,'debit',l.debit,'credit',l.credit,'project_id',l.project_id,'project_name',l.project_name,'client',l.client,'service_line_key',l.service_line_key) order by l.line_number) from finance_pilot_dev.finance_next_journal_lines l where l.journal_entry_id=e.id) as finance_next_journal_lines
 from finance_pilot_dev.finance_next_journal_entries e where e.id in (select journal_entry_id from period_lines) order by e.entry_date desc,e.created_at desc limit 100
 ), project_rows as (
 select p.id,p.project_code,p.name,p.client_name,coalesce(pc.service_line_key,'unmapped') as service_line_key,p.status,
 pc.contract_value,pc.budgeted_hpp,pc.committed_cost,pc.financially_closed_at,pc.delivery_confirmed_at,
 coalesce((select sum(credit-debit) from period_lines where project_id=p.id and account_class='Pendapatan'),0) as recognized_revenue,
 coalesce((select sum(debit-credit) from period_lines where project_id=p.id and account_class='Beban Langsung Proyek'),0) as actual_hpp,
 coalesce((select sum(total) from selected_invoices where pilot_project_id=p.id and document_date between v_start_date and v_end_date),0) as billed_amount,
 coalesce((select sum(total) from rec where pilot_project_id=p.id),0) as cash_collected
 from finance_pilot_dev.projects p left join finance_pilot_dev.finance_next_project_controls pc on pc.project_id=p.id where p.deleted_at is null and (p_service is null or pc.service_line_key=p_service) and (p_project is null or p.id=p_project) and (p_client is null or p.client_name=p_client)
 ), cashflow as (
 select coalesce(sum(debit-credit) filter(where business_event not in ('asset_purchase','owner_receivable','opening_adjustment')),0) as operating,
 coalesce(sum(debit-credit) filter(where business_event in ('asset_purchase','owner_receivable')),0) as investing,
 coalesce(sum(debit-credit) filter(where business_event='opening_adjustment'),0) as financing
 from period_lines where coa_code=ac->>'cash'
 ), report as (
 select jsonb_build_object(
 'income',jsonb_build_array(jsonb_build_object('label','Recognized Revenue','value',revenue),jsonb_build_object('label','Direct Project Cost / HPP','value',-hpp),jsonb_build_object('label','Gross Profit','value',revenue-hpp),jsonb_build_object('label','Operating Expense','value',-opex),jsonb_build_object('label','Operating Profit','value',revenue-hpp-opex),jsonb_build_object('label','Other Expense','value',-other),jsonb_build_object('label','Tax Expense','value',-tax),jsonb_build_object('label','Net Profit','value',revenue-hpp-opex-other-tax)),
 'position',coalesce((select jsonb_agg(jsonb_build_object('label',code||' · '||name,'value',case when account_class='Aset' then closing else -closing end,'coa_code',code)) from balances where account_class in ('Aset','Kewajiban','Ekuitas')), '[]'::jsonb)||jsonb_build_array(jsonb_build_object('label','Unclosed retained profit','value',coalesce((select sum(case when account_class='Pendapatan' then credit-debit else credit-debit end) from dim where entry_date<=v_end_date and account_class in ('Pendapatan','Beban Langsung Proyek','Beban Operasional','Beban Non-Operasional','Pajak')),0))),
 'trial',coalesce((select jsonb_agg(jsonb_build_object('label',code||' · '||name,'value',closing,'coa_code',code,'opening',opening,'debit',debit,'credit',credit)) from balances),'[]'::jsonb),
 'cashflow',jsonb_build_array(jsonb_build_object('label','Operating activities','value',cf.operating),jsonb_build_object('label','Investing activities','value',cf.investing),jsonb_build_object('label','Financing activities','value',cf.financing),jsonb_build_object('label','Net cash movement','value',cf.operating+cf.investing+cf.financing)),
 'equity',coalesce((select jsonb_agg(jsonb_build_object('label',code||' · '||name,'value',-closing,'opening',-opening,'change',credit-debit,'coa_code',code)) from balances where account_class='Ekuitas'),'[]'::jsonb)||jsonb_build_array(jsonb_build_object('label','Period retained profit','value',revenue-hpp-opex-other-tax)),
 'aging',coalesce((select jsonb_agg(jsonb_build_object('label','AR · '||document_number||' · '||client,'value',asof_balance,'due_date',due_date,'days_overdue',greatest(v_end_date-due_date,0),'aging_bucket',case when due_date>=v_end_date then 'Current' when v_end_date-due_date<=30 then '1–30' when v_end_date-due_date<=60 then '31–60' when v_end_date-due_date<=90 then '61–90' else '>90' end,'document_id',id,'coa_code',ac->>'receivable')) from selected_invoices where asof_balance>0),'[]'::jsonb)
 ||coalesce((select jsonb_agg(jsonb_build_object('label','AP · '||reference||' · '||vendor,'value',balance,'due_date',due_date,'days_overdue',greatest(v_end_date-due_date,0),'aging_bucket',case when due_date>=v_end_date then 'Current' when v_end_date-due_date<=30 then '1–30' when v_end_date-due_date<=60 then '31–60' when v_end_date-due_date<=90 then '61–90' else '>90' end,'request_id',id,'journal_id',journal_id,'coa_code',ac->>'payable')) from vendor_bills where balance>0),'[]'::jsonb)
 ) as data from income cross join cashflow cf
 )
 select jsonb_build_object(
 'period',jsonb_build_object('start',v_start_date,'end',v_end_date,'view',p_view,'compare',p_compare,'comparison_start',v_cmp_start,'comparison_end',v_cmp_end,'fiscal_year',v_fy,'fiscal_start',v_fy_start),
 'updated_at',now(),'policy',pol,
 'accounts',(select coalesce(jsonb_agg(to_jsonb(c) order by c.code),'[]'::jsonb) from finance_pilot_dev.finance_coa c where is_active),
 'services',(select jsonb_agg(to_jsonb(s) order by service_line_key) from finance_pilot_dev.finance_next_service_lines s),
 'project_options',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'project_code',p.project_code,'name',p.name,'client_name',p.client_name,'service_line_key',pc.service_line_key,'status',p.status)),'[]'::jsonb) from finance_pilot_dev.projects p left join finance_pilot_dev.finance_next_project_controls pc on pc.project_id=p.id where deleted_at is null),
 'projects',(select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) from project_rows p),
 'journals',(select coalesce(jsonb_agg(to_jsonb(j)),'[]'::jsonb) from journal_rows j),
 'journal_count',(select count(distinct journal_entry_id) from period_lines),
 'posted_value',(select coalesce(sum(debit),0) from period_lines),
 'periods',(select coalesce(jsonb_agg(to_jsonb(p) order by period_month desc),'[]'::jsonb) from finance_pilot_dev.finance_next_periods p),
 'requests',(select coalesce(jsonb_agg(to_jsonb(r) order by created_at desc),'[]'::jsonb) from finance_pilot_dev.finance_next_requests r where state in ('draft','submitted','approved','rejected') or (kind='target' and (payload->>'fiscal_year')::int=v_fy)),
 'invoices',(select coalesce(jsonb_agg(to_jsonb(d)||jsonb_build_object('invoice_number',document_number,'invoice_date',document_date,'service_line_key',pilot_service_line_key,'project_id',pilot_project_id,'management_fee',management_fee,'paid',asof_paid,'balance',asof_balance,'status',asof_status,'finance_next_invoice_items',(select jsonb_agg(a||jsonb_build_object('line_total',round((a->>'quantity')::numeric*(a->>'unit_price')::numeric,2))) from jsonb_array_elements(items) a))),'[]'::jsonb) from selected_invoices d),
 'vendor_bills',(select coalesce(jsonb_agg(to_jsonb(v) order by due_date,id),'[]'::jsonb) from vendor_bills v),
 'receipts',(select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('receipt_number',document_number,'invoice_id',linked_invoice_id,'receipt_date',document_date,'amount',total,'deposit_coa_code',pilot_deposit_coa_code,'payment_reference',reference_number)),'[]'::jsonb) from rec r),
 'totals',(select to_jsonb(i)||jsonb_build_object('gross_profit',revenue-hpp,'operating_profit',revenue-hpp-opex,'net_profit',revenue-hpp-opex-other-tax,
 'billed',(select coalesce(sum(total),0) from selected_invoices where document_date between v_start_date and v_end_date),'collected',(select coalesce(sum(debit-credit),0) from period_lines where coa_code=ac->>'cash' and business_event='customer_receipt'),'outstanding',(select coalesce(sum(asof_balance),0) from selected_invoices)) from income i),
 'comparison',(select to_jsonb(p) from prior p),
 'service_stats',(select jsonb_agg(to_jsonb(s) order by revenue desc) from service_stats s),
 'cash',(select to_jsonb(l)||jsonb_build_object('reconciled',coalesce((select ledger_fingerprint=l.fingerprint and book_balance=l.book_cash from recon),false),'reconciliation',(select to_jsonb(r) from recon r),'buckets',(select coalesce(jsonb_agg(to_jsonb(b)),'[]'::jsonb) from buckets b),'operating_target',(select (payload->>'operating_target')::numeric from fund_plan),'restrictions',(select coalesce(sum(amount),0) from buckets),'free_cash',case when coalesce((select ledger_fingerprint=l.fingerprint and book_balance=l.book_cash from recon),false) and exists(select 1 from fund_plan) then l.book_cash-(select coalesce(sum(amount),0) from buckets)-l.payables-l.taxes-l.distribution else null end) from liquidity l),
 'target',jsonb_build_object('latest',(select to_jsonb(t) from target t),'original',(select payload from original_target),'monthly',(select jsonb_agg(to_jsonb(m) order by month) from monthly m),'actual',(select coalesce(sum(credit-debit),0) from dim where account_class='Pendapatan' and entry_date between v_fy_start and p_asof)),
 'reports',(select data from report),
 'outcomes',(select coalesce(jsonb_agg(to_jsonb(o)),'[]'::jsonb) from selected_outcome o),
 'quality',jsonb_build_object('policy_configured',pol is not null,'unmapped_legacy_count',(select count(*) from finance_pilot_dev.finance_transactions t where not exists(select 1 from finance_pilot_dev.finance_next_legacy_mappings m where m.source_type='finance_transaction' and m.source_id=t.id::text)),
 'ledger_difference',(select coalesce(sum(debit-credit),0) from all_lines),'unallocated_ap',(select payables-(select coalesce(sum(balance),0) from vendor_bills_all) from liquidity),'unmapped_deals',(select count(*) from outcome where service_line_key is null or (stage in ('Won','Lost') and outcome_date is null)),
 'scope','Pilot ledger only; historical finance has not been converted or reconciled. No cutover.')
 ) into result;
 return result;
end $$;
